INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-3D5F784106A6AD2F42C7','public_higher_education_research',NULL,'Adjusted Library hours as a result of the suspension of the full-time academic programme','https://www.dut.ac.za/Adjusted_Library_hours_as_a_result_of_the_suspension_of_the_full_time_academic_programme/',NULL,'Durban University of Technology',NULL,'South Africa','Africa','public_university',NULL,NULL,'2026-10-04T10:27:15.200Z','institutional_primary','en','Dear Staff and Students As a result of the suspension of the full-time academic programme by the DUT Executive Management, Library Management has adjusted the Library hours as follows: 28 February 2013 All site Libraries will close at 16:30 01 March 2013 All sites Libraries will be opened at 07:30 and close at 16:30 02 March 2013 Alan Pittendrigh (Steve Biko) and BM Patel (ML Sultan ) Libraries will be opened 09:00 – 17:00 OBO Lucille Webster - Acting Director: DUT Library','Dear Staff and Students As a result of the suspension of the full-time academic programme by the DUT Executive Management, Library Management has adjusted the Library hours as follows: 28 February 2013 All site Libraries will close at 16:30 01 March 2013 All sites Libraries will be opened at 07:30 and close at 16:30 02 March 2013 Alan Pittendrigh (Steve Biko) and BM Patel (ML Sultan ) Libraries will be opened 09:00 – 17:00 OBO Lucille Webster - Acting Director: DUT Library',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://www.dut.ac.za/Adjusted_Library_hours_as_a_result_of_the_suspension_of_the_full_time_academic_programme/',NULL,3,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','3b2450af948bd58735dbad9b9c914ea283da6403f3ccc7d22bcbadb6cef009c1','3d5f784106a6ad2f42c7d3ea6925dc579fa151f3bab3a75376d241031fb3cda1',1,1,1,1 FROM sources WHERE root_url='https://www.dut.ac.za/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
