INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-613B734EAE4342DA1E8C','public_higher_education_research',NULL,'DUT Community Health Studies Department Partners With USA University On Ubuntu Project','https://www.dut.ac.za/DUT_Community_Health_Studies_Department_Partners_With_USA_University_On_Ubuntu_Project/',NULL,'Durban University of Technology',NULL,'South Africa','Africa','public_university',NULL,NULL,'2026-10-04T10:27:16.789Z','institutional_primary','en','The Department of Community Health Studies (Child and Youth Care Programme) at the Durban University of Technology has teamed up with Brigham Young University (BYU) in Utah, USA to conduct an independent research study titled The Ubuntu Project. The study is funded by BYU and focuses on how ubuntu is manifested within the context of daily family life and processes in KwaZulu-Natal, South Africa. It is centered on the Nguni idea of umuntu ngumuntu ngabantu (a person is a person because of other people). The project is being driven by eight individuals, namely Professor Ray Bhagwan, Seshnum Harilal, Stephanie Blickfeldt, Professor Randal Day, Sam Pereyra, Larri- Lea Day, Pamla Pangwa and Bongani Soxujwa. Each university is represented by two academics and two students. The planning for the research study began early in the month of June upon the arrival of the professors from BYU. Data col','The Department of Community Health Studies (Child and Youth Care Programme) at the Durban University of Technology has teamed up with Brigham Young University (BYU) in Utah, USA to conduct an independent research study titled The Ubuntu Project. The study is funded by BYU and focuses on how ubuntu is manifested within the context of daily family life and processes in KwaZulu-Natal, South Africa. It is centered on the Nguni idea of umuntu ngumuntu ngabantu (a person is a person because of other people). The project is being driven by eight individuals, namely Professor Ray Bhagwan, Seshnum Harilal, Stephanie Blickfeldt, Professor Randal Day, Sam Pereyra, Larri- Lea Day, Pamla Pangwa and Bongani Soxujwa. Each university is represented by two academics and two students. The planning for the research study began early in the month of June upon the arrival of the professors from BYU. Data col',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://www.dut.ac.za/DUT_Community_Health_Studies_Department_Partners_With_USA_University_On_Ubuntu_Project/',NULL,3,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','6f32b01f8293ff8b4770652d7b92e6f2056fbe2768039f8f09abb873e73d0cf1','613b734eae4342da1e8c93b06756c71cc342385c7a87b4c8c6c181aecce0991c',1,1,1,1 FROM sources WHERE root_url='https://www.dut.ac.za/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
INSERT INTO document_search(document_id,search_text,updated_at) SELECT id,'dut community health studies department partners with usa university on ubuntu project the department of community health studies child and youth care programme at the durban university of technology has teamed up with brigham young university byu in utah usa to conduct an independent research study titled the ubuntu project. the study is funded by byu and focuses on how ubuntu is manifested within the context of daily family life and processes in kwazulu-natal south africa. it is centered on the nguni idea of umuntu ngumuntu ngabantu a person is a person because of other people . the project is being driven by eight individuals namely professor ray bhagwan seshnum harilal stephanie blickfeldt professor randal day sam pereyra larri- lea day pamla pangwa and bongani soxujwa. each university is represented by two academics and two students. the planning for the research study began early in the month of june upon the arrival of the professors from byu. data col public higher education research',CURRENT_TIMESTAMP FROM documents WHERE canonical_hash='613b734eae4342da1e8c93b06756c71cc342385c7a87b4c8c6c181aecce0991c' ON CONFLICT(document_id) DO UPDATE SET search_text=excluded.search_text,updated_at=CURRENT_TIMESTAMP;
