INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-DB3417B4D4F7B087123D','public_higher_education_research',NULL,'DUT receives R10 Million Funding from the Department of Science and Technology','https://www.dut.ac.za/DUT_receives_R10_Million_Funding_from_the_Department_of_Science_and_Technology/',NULL,'Durban University of Technology',NULL,'South Africa','Africa','public_university',NULL,NULL,'2026-10-04T10:27:16.549Z','institutional_primary','en','The Department of Science and Technology has granted the Durban University of Technology (DUT) R10million for the manufacture of six 5kW hybrid power plants for delivery in 2012 and 2013.... The Department of Science and Technology has granted the Durban University of Technology (DUT) R10million for the manufacture of six 5kW hybrid power plants for delivery in 2012 and 2013. The design and manufacture of Hybrid Renewable Energy Systems (HRES) for rural communities is at the core of the project. The project consists of the design of cutting edge technology that is being developed by DUT, with the help of local and international partners. Communities in the Nongoma area of KwaZulu-Natal will be the recipients of the HRES as they have been identified by local authorities as part of its economic and service delivery plan. Fred D','The Department of Science and Technology has granted the Durban University of Technology (DUT) R10million for the manufacture of six 5kW hybrid power plants for delivery in 2012 and 2013.... The Department of Science and Technology has granted the Durban University of Technology (DUT) R10million for the manufacture of six 5kW hybrid power plants for delivery in 2012 and 2013. The design and manufacture of Hybrid Renewable Energy Systems (HRES) for rural communities is at the core of the project. The project consists of the design of cutting edge technology that is being developed by DUT, with the help of local and international partners. Communities in the Nongoma area of KwaZulu-Natal will be the recipients of the HRES as they have been identified by local authorities as part of its economic and service delivery plan. Fred D',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://www.dut.ac.za/DUT_receives_R10_Million_Funding_from_the_Department_of_Science_and_Technology/',NULL,3,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','bb8ae2457522a044abeab9e3e82e1e1f3a87c4fb8a7bb7643f07ca0e8c7d9f7b','db3417b4d4f7b087123d51ad58eb57e30e978a43e0e0faa8e8db5f30b9e02c1d',1,1,1,1 FROM sources WHERE root_url='https://www.dut.ac.za/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
INSERT INTO document_search(document_id,search_text,updated_at) SELECT id,'dut receives r10 million funding from the department of science and technology the department of science and technology has granted the durban university of technology dut r10million for the manufacture of six 5kw hybrid power plants for delivery in 2012 and 2013.... the department of science and technology has granted the durban university of technology dut r10million for the manufacture of six 5kw hybrid power plants for delivery in 2012 and 2013. the design and manufacture of hybrid renewable energy systems hres for rural communities is at the core of the project. the project consists of the design of cutting edge technology that is being developed by dut with the help of local and international partners. communities in the nongoma area of kwazulu-natal will be the recipients of the hres as they have been identified by local authorities as part of its economic and service delivery plan. fred d public higher education research',CURRENT_TIMESTAMP FROM documents WHERE canonical_hash='db3417b4d4f7b087123d51ad58eb57e30e978a43e0e0faa8e8db5f30b9e02c1d' ON CONFLICT(document_id) DO UPDATE SET search_text=excluded.search_text,updated_at=CURRENT_TIMESTAMP;
