INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-6A772BB148A49B8D14F2','public_higher_education_research',NULL,'DUT to Confer honorary Doctor of Technology Degree in Health Sciences to Ela Gandhi','https://www.dut.ac.za/DUT_to_Confer_honorary_Doctor_of_Technology_Degree_in_Health_Sciences_to_Ela_Gandhi/',NULL,'Durban University of Technology',NULL,'South Africa','Africa','public_university',NULL,NULL,'2026-10-04T10:27:12.219Z','institutional_primary','en','The Durban University of Technology will confer an honorary Doctor of Technology Degree in Health Sciences to Ela Gandhi, in recognition of her untiring commitment to community welfare, non-violence and reconciliation in South Africa and internationally. The honorary doctorate is also being conferred to Gandhi in recognition of her invaluable contributions to DUT; including her recent role as Chancellor of the University. Gandhi, a former DUT Chancellor, will receive this award during the University’s graduation ceremony in Durban on Thursday September 6, 2012. Ela is the granddaughter of the late Mahatma Gandhi and is a peace activist and former ANC Member of Parliament. She was born at the then Phoenix Settlement where Indians, Coloureds, Whites and Africans lived in harmony. This is also where Mahatma Gandhi dreamt of building a non-racial society. Ela matriculated at the former Durba','The Durban University of Technology will confer an honorary Doctor of Technology Degree in Health Sciences to Ela Gandhi, in recognition of her untiring commitment to community welfare, non-violence and reconciliation in South Africa and internationally. The honorary doctorate is also being conferred to Gandhi in recognition of her invaluable contributions to DUT; including her recent role as Chancellor of the University. Gandhi, a former DUT Chancellor, will receive this award during the University’s graduation ceremony in Durban on Thursday September 6, 2012. Ela is the granddaughter of the late Mahatma Gandhi and is a peace activist and former ANC Member of Parliament. She was born at the then Phoenix Settlement where Indians, Coloureds, Whites and Africans lived in harmony. This is also where Mahatma Gandhi dreamt of building a non-racial society. Ela matriculated at the former Durba',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://www.dut.ac.za/DUT_to_Confer_honorary_Doctor_of_Technology_Degree_in_Health_Sciences_to_Ela_Gandhi/',NULL,4,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','011b017d85cfbd7380c1d3c70df57c9bf7805807f403ca0514ea668cdfa01b49','6a772bb148a49b8d14f214070cf997a3212d2f56f945cd17ac9cbc442f30c3fe',1,1,1,1 FROM sources WHERE root_url='https://www.dut.ac.za/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
