INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-BE29AC31CF0269E57D42','public_higher_education_research',NULL,'Department of Environmental Health - Mangosuthu University of Technology','https://www.mut.ac.za/faculty-of-applied-and-health-sciences/department-of-environmental-health-2/',NULL,'Mangosuthu University of Technology',NULL,'South Africa','Africa','public_university',NULL,NULL,'2026-10-04T10:28:08.336Z','institutional_primary','en','The purpose of this programme is to produce a corps of Environmental Health Practitioners that will be able to implement the principles of risk assessment and management in order to improve the health of the community and contribute to sustainable development. The curriculum will enable them to be able to evaluate the effectiveness and efficiency of control measures in order to make necessary improvements. In addition, they will be able to apply research skills and interpret and apply legislation, regulations and policies related to Environmental Health and to advise/educate role players on specific issues. It is also intended that the Environmental Health Practitioner who graduates with this qualification will function as a member of a multi-disciplinary team of professionals in accordance with the scope of the profession. This graduate is expected to be able to communicate effectively,','The purpose of this programme is to produce a corps of Environmental Health Practitioners that will be able to implement the principles of risk assessment and management in order to improve the health of the community and contribute to sustainable development. The curriculum will enable them to be able to evaluate the effectiveness and efficiency of control measures in order to make necessary improvements. In addition, they will be able to apply research skills and interpret and apply legislation, regulations and policies related to Environmental Health and to advise/educate role players on specific issues. It is also intended that the Environmental Health Practitioner who graduates with this qualification will function as a member of a multi-disciplinary team of professionals in accordance with the scope of the profession. This graduate is expected to be able to communicate effectively,',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://www.mut.ac.za/faculty-of-applied-and-health-sciences/department-of-environmental-health-2/',NULL,3,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','a76f6b4dfeb0b7119403563f2f2d31cde4ecbdb7be6e8d4d301fa8a0bdca75d2','be29ac31cf0269e57d42fdb61971fb70a4c6e2d7c52d049662688f64e00ee7cf',1,1,1,1 FROM sources WHERE root_url='https://www.mut.ac.za/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
