INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-CAF83B89855F136DDB58','public_higher_education_research',NULL,'Department of Office Technology - Mangosuthu University of Technology','https://www.mut.ac.za/faculty-of-management-sciences/department-of-office-technology/',NULL,'Mangosuthu University of Technology',NULL,'South Africa','Africa','public_university',NULL,NULL,'2026-10-04T10:28:08.402Z','institutional_primary','en','Office Technology is the term for all the equipment and technology used in an office. It could be physical technology such as computers, phone systems, printers, wifi routers, scanners, and copiers, but it also includes software, IT systems, access and timecoding systems, and any other technological support. This is a fast-evolving discipline as technology is changing very quickly all the time. So one of the jobs of the office technologist is to stay alert for all developments in technology and to analyse how they can be adopted forby their employers.','Office Technology is the term for all the equipment and technology used in an office. It could be physical technology such as computers, phone systems, printers, wifi routers, scanners, and copiers, but it also includes software, IT systems, access and timecoding systems, and any other technological support. This is a fast-evolving discipline as technology is changing very quickly all the time. So one of the jobs of the office technologist is to stay alert for all developments in technology and to analyse how they can be adopted forby their employers.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://www.mut.ac.za/faculty-of-management-sciences/department-of-office-technology/',NULL,3,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','3dc873b4e9f05142efbc88a8b83898e1b55241b6bc2b24258d33daa3b61570c1','caf83b89855f136ddb5888851e281d5e77b3668dd80562a384cbd93fd87b9a17',1,1,1,1 FROM sources WHERE root_url='https://www.mut.ac.za/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
