INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-81C336B08813E59BB190','public_higher_education_research',NULL,'DLRRD Launches 2026 Work Integrated Learning Programme at Mangosuthu University of Technology - Mangosuthu University of Technology','https://www.mut.ac.za/dlrrd-launches-2026-work-integrated-learning-programme-at-mangosuthu-university-of-technology/',NULL,'Mangosuthu University of Technology',NULL,'South Africa','Africa','public_university',NULL,NULL,'2026-10-04T10:28:04.060Z','institutional_primary','en','The National Department of Land Reform and Rural Development (DLRRD) has officially signalled a new chapter for aspiring geomatics professionals. On 25 February 2026, the Office of the Chief Surveyor-General launched the 2026 Work Integrated Learning (WIL) programme at Mangosuthu University of Technology (MUT). The initiative underscores the department’s commitment to bridging the gap between lecture hall theory and the high-stakes reality of professional surveying.','The National Department of Land Reform and Rural Development (DLRRD) has officially signalled a new chapter for aspiring geomatics professionals. On 25 February 2026, the Office of the Chief Surveyor-General launched the 2026 Work Integrated Learning (WIL) programme at Mangosuthu University of Technology (MUT). The initiative underscores the department’s commitment to bridging the gap between lecture hall theory and the high-stakes reality of professional surveying.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://www.mut.ac.za/dlrrd-launches-2026-work-integrated-learning-programme-at-mangosuthu-university-of-technology/',NULL,4,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','c13deb1d35be611932931f559a437bc7184075e17ae4617bf87e2113279d66ff','81c336b08813e59bb1907872f4a3288b999620f50e895526ebc46f58d8803910',1,1,1,1 FROM sources WHERE root_url='https://www.mut.ac.za/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
