INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-04D4C510586450ADBDA4','public_higher_education_research',NULL,'Mangosuthu University of Technology researcher achieves prestigious Y2 NRF rating - Mangosuthu University of Technology','https://www.mut.ac.za/mangosuthu-university-of-technology-researcher-achieves-prestigious-y2-nrf-rating/',NULL,'Mangosuthu University of Technology',NULL,'South Africa','Africa','public_university',NULL,NULL,'2026-10-04T10:28:12.229Z','institutional_primary','en','The Office of the Deputy Vice-Chancellor: Research, Innovation and Engagement (RIE) at Mangosuthu University of Technology (MUT) proudly announces that Dr Nkululeko Nkosi has been awarded a prestigious Y2 rating by the National Research Foundation (NRF). Dr Nkosi, a Lecturer in the Department of Chemical Engineering within the Faculty of Engineering, received the peer-reviewed recognition following his 2026 rating application. Effective from 1 January 2026, this rating establishes him among South Africa’s most promising emerging researchers.','The Office of the Deputy Vice-Chancellor: Research, Innovation and Engagement (RIE) at Mangosuthu University of Technology (MUT) proudly announces that Dr Nkululeko Nkosi has been awarded a prestigious Y2 rating by the National Research Foundation (NRF). Dr Nkosi, a Lecturer in the Department of Chemical Engineering within the Faculty of Engineering, received the peer-reviewed recognition following his 2026 rating application. Effective from 1 January 2026, this rating establishes him among South Africa’s most promising emerging researchers.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://www.mut.ac.za/mangosuthu-university-of-technology-researcher-achieves-prestigious-y2-nrf-rating/',NULL,3,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','e0dac202c14075b57381416f2b70ce58aaf70f366357dac5ef7553a16af030be','04d4c510586450adbda4106cd022d53bec061817c6b7f7dec212af6a4449bb3a',1,1,1,1 FROM sources WHERE root_url='https://www.mut.ac.za/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
