INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-88D7462F3EDC6E387D89','public_higher_education_research',NULL,'MUT and UWC Technology Transfer Offices join forces to boost research commercialisation - Mangosuthu University of Technology','https://www.mut.ac.za/mut-and-uwc-technology-transfer-offices-join-forces-to-boost-research-commercialisation/',NULL,'Mangosuthu University of Technology',NULL,'South Africa','Africa','public_university',NULL,NULL,'2026-10-04T10:28:12.480Z','institutional_primary','en','Two members of the Research directorate’s Technology Transfer Office (TTO) have just returned from a vital benchmarking and knowledge-sharing visit from 11 to 15 May 2026, to the University of the Western Cape (UWC). Dr Mandla Hlongwane, Deputy Director: Technology Transfer, said the initiative forms part of a capacity development programme for Universities of Technology (UoTs), fully supported by the Technological Higher Education Network South Africa (THENSA). The strategic engagement was designed to strengthen institutional capabilities in technology transfer and intellectual property (IP) management by exchanging proven best practices between the two specialised offices.','Two members of the Research directorate’s Technology Transfer Office (TTO) have just returned from a vital benchmarking and knowledge-sharing visit from 11 to 15 May 2026, to the University of the Western Cape (UWC). Dr Mandla Hlongwane, Deputy Director: Technology Transfer, said the initiative forms part of a capacity development programme for Universities of Technology (UoTs), fully supported by the Technological Higher Education Network South Africa (THENSA). The strategic engagement was designed to strengthen institutional capabilities in technology transfer and intellectual property (IP) management by exchanging proven best practices between the two specialised offices.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://www.mut.ac.za/mut-and-uwc-technology-transfer-offices-join-forces-to-boost-research-commercialisation/',NULL,3,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','615d6e5570193482ea368c751a986333cac4aad0f901ab1507e0ec0c74934077','88d7462f3edc6e387d89923691dc6053cbed6019b8a80a09038de9606fea3edf',1,1,1,1 FROM sources WHERE root_url='https://www.mut.ac.za/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
