INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-7D15C720F54C7A5C3F5A','public_higher_education_research',NULL,'News Archive Item','https://www.ufs.ac.za/templates/news-archive/campus-news/2026/september/ufs-student-leaders-gain-african-perspectives-through-global-citizenship-programme-in-kenya',NULL,'University of the Free State','UFS EDCM','South Africa','Africa','public_university',NULL,NULL,'2026-10-04T10:30:25.596Z','institutional_primary','en','Being a global citizen in Africa today means learning to see beyond the boundaries of one''s own experience.Through the Global Citizenship Developmental Programme, student leaders are doing just that in Kenya, engaging with universities and public institutions to deepen their understanding of leadership, governance and development on the continent. The programme forms part of the UFS Division of Student Affairs'' commitment to developing globally competent graduates who are socially responsible and equipped to contribute meaningfully to society.Now in its third year, the programme has expanded from partnerships in Southern Africa to East Africa through a collaboration with the Co-operative University of Kenya (CUK). African universities learning from one anotherAt CUK, the UFS delegation engaged with university leadership on the role of higher education in responding to social and economic','Being a global citizen in Africa today means learning to see beyond the boundaries of one''s own experience.Through the Global Citizenship Developmental Programme, student leaders are doing just that in Kenya, engaging with universities and public institutions to deepen their understanding of leadership, governance and development on the continent. The programme forms part of the UFS Division of Student Affairs'' commitment to developing globally competent graduates who are socially responsible and equipped to contribute meaningfully to society.Now in its third year, the programme has expanded from partnerships in Southern Africa to East Africa through a collaboration with the Co-operative University of Kenya (CUK). African universities learning from one anotherAt CUK, the UFS delegation engaged with university leadership on the role of higher education in responding to social and economic',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://www.ufs.ac.za/templates/news-archive/campus-news/2026/september/ufs-student-leaders-gain-african-perspectives-through-global-citizenship-programme-in-kenya',NULL,3,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','76ed9caa98fae021c25b30697a2ae73e19d81824e84bb45fd66a9a70014fe403','7d15c720f54c7a5c3f5a4fa84ca7e29f245015a3aa5167616e8d50f04246acf0',1,1,1,1 FROM sources WHERE root_url='https://www.ufs.ac.za/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
INSERT INTO document_search(document_id,search_text,updated_at) SELECT id,'news archive item being a global citizen in africa today means learning to see beyond the boundaries of one s own experience.through the global citizenship developmental programme student leaders are doing just that in kenya engaging with universities and public institutions to deepen their understanding of leadership governance and development on the continent. the programme forms part of the ufs division of student affairs commitment to developing globally competent graduates who are socially responsible and equipped to contribute meaningfully to society.now in its third year the programme has expanded from partnerships in southern africa to east africa through a collaboration with the co-operative university of kenya cuk . african universities learning from one anotherat cuk the ufs delegation engaged with university leadership on the role of higher education in responding to social and economic public higher education research',CURRENT_TIMESTAMP FROM documents WHERE canonical_hash='7d15c720f54c7a5c3f5a4fa84ca7e29f245015a3aa5167616e8d50f04246acf0' ON CONFLICT(document_id) DO UPDATE SET search_text=excluded.search_text,updated_at=CURRENT_TIMESTAMP;
INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-6BF3820AA9CF6A054AB9','public_higher_education_research',NULL,'News Archive Item','https://www.ufs.ac.za/templates/news-archive/campus-news/2026/september/not-broken-but-unheld--a-new-un-report-asks-us-to-tend-the-forest--not-only-the-tree',NULL,'University of the Free State','UFS EDCM','South Africa','Africa','public_university',NULL,NULL,'2026-10-04T10:30:27.080Z','institutional_primary','en','Opinion article by Prof Narnia Bohler-Muller, Research Theme Leader: Flourishing Life, Directorate Research Development, University of the Free StateThere is a sentence in the middle of the United Nations’ new report on youth mental health that I have not been able to set down: “There is no ‘cure’ for being human”. Thriving, its authors write, does not mean the absence of hardship. It is a rare admission for an institution whose native idiom is targets and indicators, and it signals something larger than a change of tone.Youth Mental Health & Well-being in an Uncertain World: A Global Call to Action, produced by the UN Youth Office and the United Nations University International Institute for Global Health and launched in September’s UN General Assembly, asks governments to stop treating young people’s distress mainly as a matter of individual symptoms. Instead it proposes an ecosystem m','Opinion article by Prof Narnia Bohler-Muller, Research Theme Leader: Flourishing Life, Directorate Research Development, University of the Free StateThere is a sentence in the middle of the United Nations’ new report on youth mental health that I have not been able to set down: “There is no ‘cure’ for being human”. Thriving, its authors write, does not mean the absence of hardship. It is a rare admission for an institution whose native idiom is targets and indicators, and it signals something larger than a change of tone.Youth Mental Health & Well-being in an Uncertain World: A Global Call to Action, produced by the UN Youth Office and the United Nations University International Institute for Global Health and launched in September’s UN General Assembly, asks governments to stop treating young people’s distress mainly as a matter of individual symptoms. Instead it proposes an ecosystem m',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://www.ufs.ac.za/templates/news-archive/campus-news/2026/september/not-broken-but-unheld--a-new-un-report-asks-us-to-tend-the-forest--not-only-the-tree',NULL,2,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','a4ff2e742e3d0298b741df5e197073ddb3d5052e23348acb71bbb71e3db6b57c','6bf3820aa9cf6a054ab99cb0ce19938ccc36b26d2328bcebebfe6972f459bc75',1,1,1,1 FROM sources WHERE root_url='https://www.ufs.ac.za/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
