INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-DC78826B461CAD121642','public_higher_education_research',NULL,'News Archive Item','https://www.ufs.ac.za/templates/news-archive/campus-news/2026/september/where-christianity-and-xhosa-identity-meet--liso-rulashe-s-prize-winning-research',NULL,'University of the Free State','UFS EDCM','South Africa','Africa','public_university',NULL,NULL,'2026-10-04T10:30:26.613Z','institutional_primary','en','What happens when a religious faith that calls for a break with the past meets a cultural practice deeply rooted in identity?For University of the Free State postgraduate student Liso Rulashe, the question lies at the heart of his research into how Pentecostal Christians negotiate their faith, Xhosa cultural identity, and masculinity. His exploration of this complex intersection has now earned him the Monica Wilson Prize, making him the first University of the Free State student to receive the prestigious postgraduate anthropology award. The Monica Wilson Prize was introduced in 2009 to commemorate Monica Wilson''s contributions to Anthropology. The prize is awarded to the best student essay submitted by a postgraduate student as a paper at the annual Anthropology Southern Africa conference. Rulashe was selected as one of four finalists at the annual Anthropology Southern Africa conferenc','What happens when a religious faith that calls for a break with the past meets a cultural practice deeply rooted in identity?For University of the Free State postgraduate student Liso Rulashe, the question lies at the heart of his research into how Pentecostal Christians negotiate their faith, Xhosa cultural identity, and masculinity. His exploration of this complex intersection has now earned him the Monica Wilson Prize, making him the first University of the Free State student to receive the prestigious postgraduate anthropology award. The Monica Wilson Prize was introduced in 2009 to commemorate Monica Wilson''s contributions to Anthropology. The prize is awarded to the best student essay submitted by a postgraduate student as a paper at the annual Anthropology Southern Africa conference. Rulashe was selected as one of four finalists at the annual Anthropology Southern Africa conferenc',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://www.ufs.ac.za/templates/news-archive/campus-news/2026/september/where-christianity-and-xhosa-identity-meet--liso-rulashe-s-prize-winning-research',NULL,2,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','086f4e3bc1f70bdf922ecbdf2fcc86f47976499f6c42a1db4c13c01107285bad','dc78826b461cad1216427599133d810a88d2c5adfea06b3357efd01ed4119c5d',1,1,1,1 FROM sources WHERE root_url='https://www.ufs.ac.za/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
INSERT INTO document_search(document_id,search_text,updated_at) SELECT id,'news archive item what happens when a religious faith that calls for a break with the past meets a cultural practice deeply rooted in identity for university of the free state postgraduate student liso rulashe the question lies at the heart of his research into how pentecostal christians negotiate their faith xhosa cultural identity and masculinity. his exploration of this complex intersection has now earned him the monica wilson prize making him the first university of the free state student to receive the prestigious postgraduate anthropology award. the monica wilson prize was introduced in 2009 to commemorate monica wilson s contributions to anthropology. the prize is awarded to the best student essay submitted by a postgraduate student as a paper at the annual anthropology southern africa conference. rulashe was selected as one of four finalists at the annual anthropology southern africa conferenc public higher education research',CURRENT_TIMESTAMP FROM documents WHERE canonical_hash='dc78826b461cad1216427599133d810a88d2c5adfea06b3357efd01ed4119c5d' ON CONFLICT(document_id) DO UPDATE SET search_text=excluded.search_text,updated_at=CURRENT_TIMESTAMP;
INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-17002A123ECE1B491D04','public_higher_education_research',NULL,'News Archive Item','https://www.ufs.ac.za/templates/news-archive/campus-news/2026/october/ufs-equips-nearly-580-free-state-teachers-with-new-classroom-approaches',NULL,'University of the Free State','UFS EDCM','South Africa','Africa','public_university',NULL,NULL,'2026-10-04T10:30:29.032Z','institutional_primary','en','The University of the Free State (UFS), in partnership with the Free State Department of Education and the Education, Training and Development Practices Sector Education and Training Authority (ETDP SETA), is supporting the professional development of approximately 580 teachers from all five districts of the province.The teachers are taking part in two UFS Short Learning Programmes (SLPs): Innovative Instructional Techniques for Intermediate Phase Mathematics, and Teacher Professional Development for Digital Mobile Learning. Bringing new approaches into the classroomThe programmes help teachers develop new approaches to teaching Intermediate Phase Mathematics and using digital mobile learning in their classrooms.For UFS, the initiative also provides an opportunity to connect the University’s expertise in teacher education with the needs of schools in the province.Speaking at the opening ','The University of the Free State (UFS), in partnership with the Free State Department of Education and the Education, Training and Development Practices Sector Education and Training Authority (ETDP SETA), is supporting the professional development of approximately 580 teachers from all five districts of the province.The teachers are taking part in two UFS Short Learning Programmes (SLPs): Innovative Instructional Techniques for Intermediate Phase Mathematics, and Teacher Professional Development for Digital Mobile Learning. Bringing new approaches into the classroomThe programmes help teachers develop new approaches to teaching Intermediate Phase Mathematics and using digital mobile learning in their classrooms.For UFS, the initiative also provides an opportunity to connect the University’s expertise in teacher education with the needs of schools in the province.Speaking at the opening ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://www.ufs.ac.za/templates/news-archive/campus-news/2026/october/ufs-equips-nearly-580-free-state-teachers-with-new-classroom-approaches',NULL,1,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','3a6b6677cfcbd9894f6466222de050f56c3e7a82aceba583410bac5490fcdafb','17002a123ece1b491d04a9d6f3229f51b28b7fc40f31a1fffebde080e0ab41ee',1,1,1,1 FROM sources WHERE root_url='https://www.ufs.ac.za/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
