INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-A9E0FA77C1B9055D52E0','research',NULL,'Researchers Report Dwarf Novae Unlikely to Be Type Ia Supernova Progenitors----Yunnan Observatories','https://english.ynao.cas.cn/research/rp/202609/t20260930_1201601.html',NULL,'*Yunnan Observatories',NULL,'China','Asia','official_research_institution',NULL,NULL,'2026-10-04T10:28:18.469Z','institutional_primary','en','Recently, PhD student LI Ruijie and Prof. WANG Bo from Yunnan Observatories, Chinese Academy of Sciences, reported new findings on dwarf novae. The team found that cyclic accretion in dwarf novae cannot sustain stable hydrogen burning on white dwarfs. Recurrent nova eruptions reduce the mass retention efficiency of white dwarfs, preventing them from growing to the Chandrasekhar mass limit through long-term accretion. Therefore, dwarf novae are unlikely to be progenitor systems of Type Ia supernovae. The study has been published in the international astronomical journal Astronomy & Astrophysics.','Recently, PhD student LI Ruijie and Prof. WANG Bo from Yunnan Observatories, Chinese Academy of Sciences, reported new findings on dwarf novae. The team found that cyclic accretion in dwarf novae cannot sustain stable hydrogen burning on white dwarfs. Recurrent nova eruptions reduce the mass retention efficiency of white dwarfs, preventing them from growing to the Chandrasekhar mass limit through long-term accretion. Therefore, dwarf novae are unlikely to be progenitor systems of Type Ia supernovae. The study has been published in the international astronomical journal Astronomy & Astrophysics.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://english.ynao.cas.cn/research/rp/202609/t20260930_1201601.html',NULL,2,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','e8047570aee4be8f22399954c03d6f39f95d69f0c79538c880e05edb0613aace','a9e0fa77c1b9055d52e0b675d3328b6fae6996663510399eec37b61113ed883e',1,1,1,1 FROM sources WHERE root_url='https://english.ynao.cas.cn/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
INSERT INTO document_search(document_id,search_text,updated_at) SELECT id,'researchers report dwarf novae unlikely to be type ia supernova progenitors----yunnan observatories recently phd student li ruijie and prof. wang bo from yunnan observatories chinese academy of sciences reported new findings on dwarf novae. the team found that cyclic accretion in dwarf novae cannot sustain stable hydrogen burning on white dwarfs. recurrent nova eruptions reduce the mass retention efficiency of white dwarfs preventing them from growing to the chandrasekhar mass limit through long-term accretion. therefore dwarf novae are unlikely to be progenitor systems of type ia supernovae. the study has been published in the international astronomical journal astronomy astrophysics. research',CURRENT_TIMESTAMP FROM documents WHERE canonical_hash='a9e0fa77c1b9055d52e0b675d3328b6fae6996663510399eec37b61113ed883e' ON CONFLICT(document_id) DO UPDATE SET search_text=excluded.search_text,updated_at=CURRENT_TIMESTAMP;
INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-EE7054DC88F62AA2C7D0','research',NULL,'Solar Physics Group----Yunnan Observatories','https://english.ynao.cas.cn/research/rg/spg/',NULL,'*Yunnan Observatories',NULL,'China','Asia','official_research_institution',NULL,NULL,'2026-10-04T10:28:21.531Z','institutional_primary','en','Solar Physics is traditionally one of YNAO’s strongest fields of research. The Solar Physics group employs many experts in this field, and has access to immense amounts of resources in terms of instrumentation. Our academic mission is divided into 4 parts: project-oriented solar research, routine observations, database services, and the development of new technologies and instrumentation.','Solar Physics is traditionally one of YNAO’s strongest fields of research. The Solar Physics group employs many experts in this field, and has access to immense amounts of resources in terms of instrumentation. Our academic mission is divided into 4 parts: project-oriented solar research, routine observations, database services, and the development of new technologies and instrumentation.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://english.ynao.cas.cn/research/rg/spg/',NULL,1,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','ac86c085c2b38bc