INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-ADD2A891F7F41B6F47DC','research',NULL,'Stellar Astrophysics Group----Yunnan Observatories','https://english.ynao.cas.cn/research/rg/sag/',NULL,'*Yunnan Observatories',NULL,'China','Asia','official_research_institution',NULL,NULL,'2026-10-04T10:28:21.550Z','institutional_primary','en','The Stellar Astrophysics Group was created in the 1970s by Academician Runqian Huang. After over 30 years of development, the group has made significant breakthroughs in unconserved binary evolution theory, stellar wind shock theory, the effects of convective overshooting on stellar evolution, stellar evolution, formation of irregular objects, the period-luminosity relation of red supergiants, and the structure of the solar convective zone, among others.','The Stellar Astrophysics Group was created in the 1970s by Academician Runqian Huang. After over 30 years of development, the group has made significant breakthroughs in unconserved binary evolution theory, stellar wind shock theory, the effects of convective overshooting on stellar evolution, stellar evolution, formation of irregular objects, the period-luminosity relation of red supergiants, and the structure of the solar convective zone, among others.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://english.ynao.cas.cn/research/rg/sag/',NULL,1,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','f8881cc74f61f6da8c9c113e008c804facb478a1fae07322b64c6d56c8419591','add2a891f7f41b6f47dc9bd02170c4de9e723b13c9e16142f5448301fd673e9b',1,1,1,1 FROM sources WHERE root_url='https://english.ynao.cas.cn/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
