INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-5E83EBBBD044FB162D2D','research',NULL,'Decoding Heat-Resilient Chloroplast Development: The Central Role of GUN1----SIPPE|Institute of Plant Physiology and Ecology, SIBS, CAS','http://english.sippe.cas.cn/Research/NewsEvents/202601/t20260105_1145212.html',NULL,'CAS Center for Excellence in Molecular Plant Sciences',NULL,'China','Asia','official_research_institution',NULL,NULL,'2026-10-04T10:28:58.932Z','institutional_primary','en','On December 31, 2025, a research article entitled “Biogenic Retrograde Signaling via GUN1 Ensures Thermotolerant Chloroplast Biogenesis during Seedling Establishment in Arabidopsis thaliana” was published in the Journal of Integrative Plant Biology (JIPB) . This study uncovers a previously unrecognized role of GUN1, a central regulator of biogenic retrograde signaling, in safeguarding chloroplast biogenesis during the earliest stages of seedling establishment under elevated temperature. In contrast to earlier work that primarily examined heat responses in established seedlings or mature plants, the authors demonstrate that chloroplast development during germination represents a particularly vulnerable developmental window. During this stage, GUN1 is indispensable for sustaining photosynthesis, chloroplast translation, and reactive oxygen species (ROS) homeostasis even under moderate heat','On December 31, 2025, a research article entitled “Biogenic Retrograde Signaling via GUN1 Ensures Thermotolerant Chloroplast Biogenesis during Seedling Establishment in Arabidopsis thaliana” was published in the Journal of Integrative Plant Biology (JIPB) . This study uncovers a previously unrecognized role of GUN1, a central regulator of biogenic retrograde signaling, in safeguarding chloroplast biogenesis during the earliest stages of seedling establishment under elevated temperature. In contrast to earlier work that primarily examined heat responses in established seedlings or mature plants, the authors demonstrate that chloroplast development during germination represents a particularly vulnerable developmental window. During this stage, GUN1 is indispensable for sustaining photosynthesis, chloroplast translation, and reactive oxygen species (ROS) homeostasis even under moderate heat',NULL,NULL,NULL,NULL,NULL,'10.1111/jipb.70127','10.1111/jipb.70127',NULL,'free','primary','not_applicable',NULL,NULL,'http://english.sippe.cas.cn/Research/NewsEvents/202601/t20260105_1145212.html',NULL,1,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','df7ed20aaf1692c745beddc268f8a02de1850f756fd6f7212de62f4e4959361e','5e83ebbbd044fb162d2de797891069e4823518e1dbe0f96e1ba1211c923eba2b',1,1,1,1 FROM sources WHERE root_url='http://english.sippe.cas.cn/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
INSERT INTO document_search(document_id,search_text,updated_at) SELECT id,'decoding heat-resilient chloroplast development the central role of gun1----sippe institute of plant physiology and ecology sibs cas on december 31 2025 a research article entitled biogenic retrograde signaling via gun1 ensures thermotolerant chloroplast biogenesis during seedling establishment in arabidopsis thaliana was published in the journal of integrative plant biology jipb . this study uncovers a previously unrecognized role of gun1 a central regulator of biogenic retrograde signaling in safeguarding chloroplast biogenesis during the earliest stages of seedling establishment under elevated temperature. in contrast to earlier work that primarily examined heat responses in established seedlings or mature plants the authors demonstrate that chloroplast development during germination represents a particularly vulnerable developmental window. during this stage gun1 is indispensable for sustaining photosynthesis chloroplast translation and reactive oxygen species ros homeostasis even under moderate heat research',CURRENT_TIMESTAMP FROM documents WHERE canonical_hash='5e83ebbbd044fb162d2de797891069e4823518e1dbe0f96e1ba1211c923eba2b' ON CONFLICT(document_id) DO UPDATE SET search_text=excluded.search_text,updated_at=CURRENT_TIMESTAMP;
