INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-1665EEDE3B1DB364B83C','research',NULL,'Professor John Wenger from University College Cork visited the Chongqing Institute of Green and Intelligent Technology, Chinese Academy of Sciences.----Chongqing Insitute of Green and Intelligent Technology','http://english.cigit.cas.cn/nw/academicactivities/202503/t20250305_903121.html',NULL,'Chongqing Institute of Green and Intelligent Technology','中国科学院','China','Asia','official_research_institution',NULL,NULL,'2026-10-04T10:31:03.359Z','institutional_primary','en','On February 24, Professor John Wenger (University College Cork, Ireland) visited the Chongqing Institute for an academic visit via the invitation of Professor Yang Chen (Director of the Research Center for Atmospheric Environment). The visit aimed to enhance international collaboration in atmospheric chemistry and promote the deep integration of academic research and global collaboration. During his presentation, Professor John Wenger introduced the smog chamber simulation reaction system at the Research Center for Atmospheric Chemistry (CRAC) of University College Cork.','On February 24, Professor John Wenger (University College Cork, Ireland) visited the Chongqing Institute for an academic visit via the invitation of Professor Yang Chen (Director of the Research Center for Atmospheric Environment). The visit aimed to enhance international collaboration in atmospheric chemistry and promote the deep integration of academic research and global collaboration. During his presentation, Professor John Wenger introduced the smog chamber simulation reaction system at the Research Center for Atmospheric Chemistry (CRAC) of University College Cork.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'http://english.cigit.cas.cn/nw/academicactivities/202503/t20250305_903121.html',NULL,3,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','4713b09f0f89d4eea7d12debe4ffcd8913655fd44c435e7b11043fee1904906f','1665eede3b1db364b83c55e456c8981b4f4ad814fa5366d57b267894e22f0934',1,1,1,1 FROM sources WHERE root_url='http://english.cigit.cas.cn/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
