INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-575CCC1D9F54CFF73C33','research',NULL,'The Youth Innovation Promotion Association of the Chinese Academy of Sciences Holds the 2024 Chongqing Forum and Interdisciplinary Symposium----Chongqing Insitute of Green and Intelligent Technology','http://english.cigit.cas.cn/nw/academicactivities/202412/t20241227_896091.html',NULL,'Chongqing Institute of Green and Intelligent Technology','中国科学院','China','Asia','official_research_institution',NULL,NULL,'2026-10-04T10:31:04.102Z','institutional_primary','en','To promote the spirit of scientists, further enhance the exchange and cooperation among young researchers, stimulate innovative thinking, and foster interdisciplinary intellectual collisions, the Youth Promotion Association (YPA) group of the Chongqing Institute of Green and Intelligent Technology, Chinese Academy of Sciences, organized the "2024 CAS YPA Chongqing Forum and Interdisciplinary Symposium" in Chongqing on December 13, 2024. Over fifty distinguished young scholars and experts from institutions such as the Shanghai Institute of Optics and Fine Mechanics of the Chinese Academy of Sciences, Chongqing University, Shandong University, Southwest University, Suzhou University of Science and Technology, Nanjing Institute of Technology, the First Affiliated Hospital of Army Medical University, Chongqing Medical University, and the Cancer Hospital affiliated to Chongqing University, al','To promote the spirit of scientists, further enhance the exchange and cooperation among young researchers, stimulate innovative thinking, and foster interdisciplinary intellectual collisions, the Youth Promotion Association (YPA) group of the Chongqing Institute of Green and Intelligent Technology, Chinese Academy of Sciences, organized the "2024 CAS YPA Chongqing Forum and Interdisciplinary Symposium" in Chongqing on December 13, 2024. Over fifty distinguished young scholars and experts from institutions such as the Shanghai Institute of Optics and Fine Mechanics of the Chinese Academy of Sciences, Chongqing University, Shandong University, Southwest University, Suzhou University of Science and Technology, Nanjing Institute of Technology, the First Affiliated Hospital of Army Medical University, Chongqing Medical University, and the Cancer Hospital affiliated to Chongqing University, al',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'http://english.cigit.cas.cn/nw/academicactivities/202412/t20241227_896091.html',NULL,2,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','52675102a1acb612763ea3c16acc0268c067e8b85cfc305837320fdd62dede17','575ccc1d9f54cff73c33b7766a1492bd8e9c75c1369829dbc744934e3bf5aa55',1,1,1,1 FROM sources WHERE root_url='http://english.cigit.cas.cn/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
