INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-4B136F65596148DFF928','research',NULL,'Welcome to Central Institute of Medicinal and Aromatic Plants (CSIR-CIMAP)- Lucknow','https://cimap.res.in/cimhindi/pages/SandTBiotechnology.aspx',NULL,'CSIR-Ce',NULL,'India','Asia','government_research_institute',NULL,NULL,'2026-10-04T10:32:25.218Z','institutional_primary','en','जीव विज्ञान केंद्रीय सुविधा (बायोलॉजी सेंट्रल फैसिलिटी) CSIR-CIMAP की इंस्ट्रुमेंटेशन की एक अत्याधुनिक सुविधा है, जिसमें ५० से अधिक नवीनतम अत्याधुनिक उपकरण हैं। यह सुविधा सभी शोधकर्ताओं (छात्रों और कर्मचारियों) को अत्याधुनिक उपकरणों जैसे स्कैनिंग इलेक्ट्रान माइक्रोस्कोप,कॉन्फोकल माइक्रोस्कोप, जेनेटिक एनालाइजर, रीयल टाइम पी.सी.आर, अल्ट्रा-सेंट्रीफ्यूज, फ्लो साइटोमीटर, हाई स्पीड सेंट्रीफ्यूज और अन्य सभी नियमित प्रयोगशाला उपकरणों का उपयोग कर अपना शोध कार्य करने के लिए एक अनूठा मंच प्रदान करता है। बी.सी.एफ., CSIR-CIMAP की एक ऐसी केंद्रीय सुविधा है जो संस्थान के जीव विज्ञान के शोधकर्ताओं के साथ-साथ अन्य संस्थानों/विश्वविद्यालयों के शोधकर्ताओं को भी सेवा प्रदान करता है। इस सुविधा का उपयोग ओपेन डे. (राष्ट्रीय विज्ञान दिवस, राष्ट्रीय प्रौद्योगिकी दिवस, सी.एस.आई.आर. स्थापना दिवस, सी.आई.एम.ए.पी. वार्षिक दिवस, आदि) पर भी किया जाता है ताकि स्कूल/कॉलेज के विज्ञान के छात्रों और प्राध्यापकों को इसके द्','जीव विज्ञान केंद्रीय सुविधा (बायोलॉजी सेंट्रल फैसिलिटी) CSIR-CIMAP की इंस्ट्रुमेंटेशन की एक अत्याधुनिक सुविधा है, जिसमें ५० से अधिक नवीनतम अत्याधुनिक उपकरण हैं। यह सुविधा सभी शोधकर्ताओं (छात्रों और कर्मचारियों) को अत्याधुनिक उपकरणों जैसे स्कैनिंग इलेक्ट्रान माइक्रोस्कोप,कॉन्फोकल माइक्रोस्कोप, जेनेटिक एनालाइजर, रीयल टाइम पी.सी.आर, अल्ट्रा-सेंट्रीफ्यूज, फ्लो साइटोमीटर, हाई स्पीड सेंट्रीफ्यूज और अन्य सभी नियमित प्रयोगशाला उपकरणों का उपयोग कर अपना शोध कार्य करने के लिए एक अनूठा मंच प्रदान करता है। बी.सी.एफ., CSIR-CIMAP की एक ऐसी केंद्रीय सुविधा है जो संस्थान के जीव विज्ञान के शोधकर्ताओं के साथ-साथ अन्य संस्थानों/विश्वविद्यालयों के शोधकर्ताओं को भी सेवा प्रदान करता है। इस सुविधा का उपयोग ओपेन डे. (राष्ट्रीय विज्ञान दिवस, राष्ट्रीय प्रौद्योगिकी दिवस, सी.एस.आई.आर. स्थापना दिवस, सी.आई.एम.ए.पी. वार्षिक दिवस, आदि) पर भी किया जाता है ताकि स्कूल/कॉलेज के विज्ञान के छात्रों और प्राध्यापकों को इसके द्',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://cimap.res.in/cimhindi/pages/SandTBiotechnology.aspx',NULL,2,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','c1c2e2858df0301650dc9a5dd6010dddcf44d03d842d0cb19209a3334510c2f4','4b136f65596148dff9281161db73bc61aa99c3b10f264692f4510ff3beb1e6e3',1,1,1,1 FROM sources WHERE root_url='https://cimap.res.in/cimhindi/pages/AdminHomePage.aspx' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
