INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-6294CB3E7EE2B7708EE5','research',NULL,'CSIR-IIIM, GMC Kathua sign MoU to Boost Clinical Research, Healtcare Innovation in J&#038;K. &#8211; सीएसआईआर-भारतीय समवेत औषध संस्थान','https://iiim.res.in/csir-iiim-gmc-kathua-sign-mou-to-boost-clinical-research-healtcare-innovation-in-jk/',NULL,'CSIR-In',NULL,'India','Asia','government_research_institute','2026-04-12T12:14:00+05:30',NULL,'2026-10-04T10:34:51.505Z','institutional_primary','en','[vc_row][vc_column][vc_single_image image=28689 img_size=full alignment=center css_animation=fadeIn css=][/vc_column][/vc_row][vc_row][vc_column][vc_text_separator title=CSIR-IIIM, 11th April 2026 title_align=separator_align_left color=turquoise border_width=2 css_animation=fadeInLeft css=][/vc_column][/vc_row][vc_row][vc_column][vc_column_text css=] CSIR-IIIM Jammu and Government Medical College Kathua formalise a strategic MoU to advance clinical research and healthcare innovation in Jammu & Kashmir. In the presence of Union Minister and Vice President, CSIR, Dr. Jitendra Singh ji, Director of CSIR-IIIM Jammu, Dr. Zabeer Ahmed, highlighted the significance of integrating cutting-edge scientific research with real-world clinical applications to drive evidence-based healthcare solutions in the region. [/vc_column_text][/vc_column][/vc_row][vc_row][vc_column][vc_separator color=turquoise ','[vc_row][vc_column][vc_single_image image=28689 img_size=full alignment=center css_animation=fadeIn css=][/vc_column][/vc_row][vc_row][vc_column][vc_text_separator title=CSIR-IIIM, 11th April 2026 title_align=separator_align_left color=turquoise border_width=2 css_animation=fadeInLeft css=][/vc_column][/vc_row][vc_row][vc_column][vc_column_text css=] CSIR-IIIM Jammu and Government Medical College Kathua formalise a strategic MoU to advance clinical research and healthcare innovation in Jammu & Kashmir. In the presence of Union Minister and Vice President, CSIR, Dr. Jitendra Singh ji, Director of CSIR-IIIM Jammu, Dr. Zabeer Ahmed, highlighted the significance of integrating cutting-edge scientific research with real-world clinical applications to drive evidence-based healthcare solutions in the region. [/vc_column_text][/vc_column][/vc_row][vc_row][vc_column][vc_separator color=turquoise ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://iiim.res.in/csir-iiim-gmc-kathua-sign-mou-to-boost-clinical-research-healtcare-innovation-in-jk/',NULL,3,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','ffc1a91eaa4029f242990f28af89ff8038ed2b29edafcbf0c8302e43b48d5283','6294cb3e7ee2b7708ee5ce44028f6dadfa818f4fc1979fe404e2ef6afb9af8f6',1,1,1,1 FROM sources WHERE root_url='https://iiim.res.in/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
