INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-E04D6A8AF9992B5C4A87','research',NULL,'CSIR-Indian Institute of Chemical Technology','https://www.iict.res.in/ABOUTUS',NULL,'CSIR-In',NULL,'India','Asia','government_research_institute',NULL,NULL,'2026-10-04T10:34:20.389Z','institutional_primary','en','Dr. Srinivasa Reddy has more than 20 years of research experience in the synthesis of natural products/medicinal chemistry/drug discovery. Dr. Reddy is best known for his application oriented organic synthesis towards human wellbeing. He is also known for the application of “Silicon-switch approach” in medicinal chemistry. In addition, the work carried out by his group on crop protection is worth highlighting. He is an author of ~120 publications and an inventor in ~35 patents. 1. 20 + Years of research experience (post-PhD) in total synthesis of natural products/medicinal chemistry/drug discovery 2. Experienced in leading drug discovery programs (7 years of pharma industry experience). 3. One of the molecules (Licogliflozin) discovered by his team in industry is currently in human clinical trials (Phase-II), where he was a project leader. 4. Out-licensed patent/technology (two nos.) dev','Dr. Srinivasa Reddy has more than 20 years of research experience in the synthesis of natural products/medicinal chemistry/drug discovery. Dr. Reddy is best known for his application oriented organic synthesis towards human wellbeing. He is also known for the application of “Silicon-switch approach” in medicinal chemistry. In addition, the work carried out by his group on crop protection is worth highlighting. He is an author of ~120 publications and an inventor in ~35 patents. 1. 20 + Years of research experience (post-PhD) in total synthesis of natural products/medicinal chemistry/drug discovery 2. Experienced in leading drug discovery programs (7 years of pharma industry experience). 3. One of the molecules (Licogliflozin) discovered by his team in industry is currently in human clinical trials (Phase-II), where he was a project leader. 4. Out-licensed patent/technology (two nos.) dev',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://www.iict.res.in/ABOUTUS',NULL,5,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','b97784d9bd12151ba8874ad9e309eb526673d4a627909f00c52b3add9b69d70e','e04d6a8af9992b5c4a87feb1bc466c7df605b7a50d39d9a47de933e6192782a4',1,1,1,1 FROM sources WHERE root_url='https://www.iict.res.in/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
INSERT INTO document_search(document_id,search_text,updated_at) SELECT id,'csir-indian institute of chemical technology dr. srinivasa reddy has more than 20 years of research experience in the synthesis of natural products medicinal chemistry drug discovery. dr. reddy is best known for his application oriented organic synthesis towards human wellbeing. he is also known for the application of silicon-switch approach in medicinal chemistry. in addition the work carried out by his group on crop protection is worth highlighting. he is an author of 120 publications and an inventor in 35 patents. 1. 20 + years of research experience post-phd in total synthesis of natural products medicinal chemistry drug discovery 2. experienced in leading drug discovery programs 7 years of pharma industry experience . 3. one of the molecules licogliflozin discovered by his team in industry is currently in human clinical trials phase-ii where he was a project leader. 4. out-licensed patent technology two nos. dev research',CURRENT_TIMESTAMP FROM documents WHERE canonical_hash='e04d6a8af9992b5c4a87feb1bc466c7df605b7a50d39d9a47de933e6192782a4' ON CONFLICT(document_id) DO UPDATE SET search_text=excluded.search_text,updated_at=CURRENT_TIMESTAMP;
