INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-4AE3780385541923C2A1','research',NULL,'अनुसंधान सहयोग','https://www.imtech.res.in/research-official-website-of-csir-institute-of-microbial-technology-ministry-of-science-technology-government-of-india/research-collaborations',NULL,'CSIR-In',NULL,'India','Asia','government_research_institute',NULL,NULL,'2026-10-04T10:35:23.561Z','institutional_primary','en','वैज्ञानिक अनुसंधान में संयुक्त प्रयासों के माध्यम से जैव प्रौद्योगिकी को आगे बढ़ाते हुए, राष्ट्रीय और अंतर्राष्ट्रीय संस्थानों के साथ सूक्ष्मजीव प्रौद्योगिकी संस्थान अनुसंधान सहयोग की खोज करें। अनुसंधान, सहयोग या कैरियर के अवसरों के बारे में पूछताछ, प्रतिक्रिया या अधिक जानकारी के लिए सूक्ष्मजीव प्रौद्योगिकी संस्थान से संपर्क करें। हम आपके इनपुट और प्रश्नों का स्वागत करते हैं। सूक्ष्मजीव प्रौद्योगिकी संस्थान सूक्ष्मजीव टाइप कल्चर कलेक्शन (MTCC) की खोज करें, जो जैव प्रौद्योगिकी, सूक्ष्म जीव विज्ञानऔर जीवन विज्ञान अनुसंधान का समर्थन करने वाले सूक्ष्मजीव उपभेदों के लिए एक प्रमुख संसाधन है। सूक्ष्मजीव प्रौद्योगिकी संस्थान फोटो गैलरी देखें जिसमें प्रमुख घटनाओं, अनुसंधान सफलताओं, वैज्ञानिक उपलब्धियों और जैव प्रौद्योगिकी और सूक्ष्म जीव विज्ञानमें सहयोगी प्रयासों को दिखाया गया है।','वैज्ञानिक अनुसंधान में संयुक्त प्रयासों के माध्यम से जैव प्रौद्योगिकी को आगे बढ़ाते हुए, राष्ट्रीय और अंतर्राष्ट्रीय संस्थानों के साथ सूक्ष्मजीव प्रौद्योगिकी संस्थान अनुसंधान सहयोग की खोज करें। अनुसंधान, सहयोग या कैरियर के अवसरों के बारे में पूछताछ, प्रतिक्रिया या अधिक जानकारी के लिए सूक्ष्मजीव प्रौद्योगिकी संस्थान से संपर्क करें। हम आपके इनपुट और प्रश्नों का स्वागत करते हैं। सूक्ष्मजीव प्रौद्योगिकी संस्थान सूक्ष्मजीव टाइप कल्चर कलेक्शन (MTCC) की खोज करें, जो जैव प्रौद्योगिकी, सूक्ष्म जीव विज्ञानऔर जीवन विज्ञान अनुसंधान का समर्थन करने वाले सूक्ष्मजीव उपभेदों के लिए एक प्रमुख संसाधन है। सूक्ष्मजीव प्रौद्योगिकी संस्थान फोटो गैलरी देखें जिसमें प्रमुख घटनाओं, अनुसंधान सफलताओं, वैज्ञानिक उपलब्धियों और जैव प्रौद्योगिकी और सूक्ष्म जीव विज्ञानमें सहयोगी प्रयासों को दिखाया गया है।',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://www.imtech.res.in/research-official-website-of-csir-institute-of-microbial-technology-ministry-of-science-technology-government-of-india/research-collaborations',NULL,4,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','3ab7393c6b4388d4d0ee31935a4fe0b2702522058b43c62f65352baec12a8717','4ae3780385541923c2a136e74a5f03f263e8a7078c643ed4e42f103ada85e150',1,1,1,1 FROM sources WHERE root_url='https://www.imtech.res.in/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
