INSERT INTO document_search(document_id,search_text,updated_at) SELECT id,'institut des sciences du vivant frederic-joliot - les bebes doues de conscience les bebes ont longtemps ete consideres comme ayant des comportements principalement automatiques qui ne s accompagnent pas d une experience subjective consciente. et pourtant des chercheurs du cea-i2bm et du cnrs montrent que les nourrissons possedent des 5 mois une forme de conscience similaire a celle des adultes. research',CURRENT_TIMESTAMP FROM documents WHERE canonical_hash='6380ebed3dea4761a043af29f6304b99fcd5d26ee5b75ee3449e219460c0f37d' ON CONFLICT(document_id) DO UPDATE SET search_text=excluded.search_text,updated_at=CURRENT_TIMESTAMP;
INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-68BC9049962A25FBE082','research',NULL,'Institut des sciences du vivant Frédéric-Joliot - Les grands modèles de langage ont-ils une conscience ?','https://www.cea.fr/presse/Pages/actualites-communiques/ntic/modeles-langage-ont-ils-conscience.aspx',NULL,'CEA',NULL,'France','Europe','public_research','2026-7-27',NULL,'2026-10-04T10:30:16.056Z','institutional_primary','fr','Dans une étude publiée début juillet, l’entreprise américaine Anthropic affirme avoir identifié un espace dans lequel Claude, son modèle d’IA, « réfléchit » à des idées sans forcément les verbaliser. Les machines disposeraient-elles d’un espace de réflexion consciente, à l’instar des humains ? Entretien de décryptage avec Stanislas Dehaene, professeur au Collège de France, directeur scientifique et responsable de l’unité de recherche en neuroimagerie cognitive de NeuroSpin, centre de recherche pour l','Dans une étude publiée début juillet, l’entreprise américaine Anthropic affirme avoir identifié un espace dans lequel Claude, son modèle d’IA, « réfléchit » à des idées sans forcément les verbaliser. Les machines disposeraient-elles d’un espace de réflexion consciente, à l’instar des humains ? Entretien de décryptage avec Stanislas Dehaene, professeur au Collège de France, directeur scientifique et responsable de l’unité de recherche en neuroimagerie cognitive de NeuroSpin, centre de recherche pour l',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://www.cea.fr/presse/Pages/actualites-communiques/ntic/modeles-langage-ont-ils-conscience.aspx',NULL,2,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','e50a66d23cceb628e0713b2a4d5648695acb531d6e6efe67bcf551afc28f6be9','68bc9049962a25fbe0829b4067ae3270a107b35eeaa445755091ab1f9d68aa63',1,1,1,1 FROM sources WHERE root_url='https://www.cea.fr/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
