INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-48A0C1A9D4D71305E919','research',NULL,'Le CNRS à Vivatech 2026 : un programme centré sur la souveraineté technologique ! | CNRS','https://www.cnrs.fr/fr/actualite/le-cnrs-vivatech-2026-un-programme-centre-sur-la-souverainete-technologique',NULL,'CNRS','Direction de la communication','France','Europe','public_research','2026-05-19T12:00:00Z',NULL,'2026-10-04T10:31:23.079Z','institutional_primary','fr','Pour sa 7ᵉ participation à VivaTech, le CNRS réaffirme son rôle central dans l’innovation deeptech, en présentant des avancées de rupture issues de laboratoires sous sa tutelle. Moteur dans l’émergence d’innovations qui impactent profondément notre société, le CNRS mettra en lumière huit start-up sur son stand. Au cours de trois journées thématiques, le CNRS propose de croiser les visions de scientifiques et industriels, qui font de la science un moteur d’autonomie et de résilience technologique. Pour le CNRS, cette édition de VivaTech sera placée sous le signe de la souveraineté technologique.','Pour sa 7ᵉ participation à VivaTech, le CNRS réaffirme son rôle central dans l’innovation deeptech, en présentant des avancées de rupture issues de laboratoires sous sa tutelle. Moteur dans l’émergence d’innovations qui impactent profondément notre société, le CNRS mettra en lumière huit start-up sur son stand. Au cours de trois journées thématiques, le CNRS propose de croiser les visions de scientifiques et industriels, qui font de la science un moteur d’autonomie et de résilience technologique. Pour le CNRS, cette édition de VivaTech sera placée sous le signe de la souveraineté technologique.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://www.cnrs.fr/fr/actualite/le-cnrs-vivatech-2026-un-programme-centre-sur-la-souverainete-technologique',NULL,3,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','6e96c5c08f57df90aa21af5b2ef1514e8e805521bd372ca9b3a041d9b31badc8','48a0c1a9d4d71305e919e84221b36c1741261a5aac3acb59ace972151d1dbab9',1,1,1,1 FROM sources WHERE root_url='https://www.cnrs.fr/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
INSERT INTO document_search(document_id,search_text,updated_at) SELECT id,'le cnrs a vivatech 2026 un programme centre sur la souverainete technologique cnrs pour sa 7 participation a vivatech le cnrs reaffirme son role central dans l innovation deeptech en presentant des avancees de rupture issues de laboratoires sous sa tutelle. moteur dans l emergence d innovations qui impactent profondement notre societe le cnrs mettra en lumiere huit start-up sur son stand. au cours de trois journees thematiques le cnrs propose de croiser les visions de scientifiques et industriels qui font de la science un moteur d autonomie et de resilience technologique. pour le cnrs cette edition de vivatech sera placee sous le signe de la souverainete technologique. research',CURRENT_TIMESTAMP FROM documents WHERE canonical_hash='48a0c1a9d4d71305e919e84221b36c1741261a5aac3acb59ace972151d1dbab9' ON CONFLICT(document_id) DO UPDATE SET search_text=excluded.search_text,updated_at=CURRENT_TIMESTAMP;
INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-764FD09CE33A7938C1B7','research',NULL,'Le CNRS fête 10 ans d’innovation avec le programme de prématuration | CNRS','https://www.cnrs.fr/fr/actualite/le-cnrs-fete-10-ans-dinnovation-avec-le-programme-de-prematuration',NULL,'CNRS','Direction de la communication','France','Europe','public_research','2024-10-28T12:00:00Z',NULL,'2026-10-04T10:31:22.939Z','institutional_primary','fr','Depuis une décennie, le programme de prématuration du CNRS accompagne les chercheuses et les chercheurs dans la valorisation de leurs découvertes, avec pour ambition de transformer les idées novatrices en preuves de concept solides. Un programme qui permet aujourd’hui à plus de 60 projets par an, dans toutes les disciplines, d’envisager leur avenir au sein du monde économique.','Depuis une décennie, le programme de prématuration du CNRS accompagne les chercheuses et les chercheurs dans la valorisation de leurs découvertes, avec pour ambition de transformer les idées novatrices en preuves de concept solides. Un programme qui permet aujourd’hui à plus de 60 projets par an, dans toutes les disciplines, d’envisager leur avenir au sein du monde économique.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://www.cnrs.fr/fr/actualite/le-cnrs-fete-10-ans-dinnovation-avec-le-programme-de-prematuration',NULL,3,'B','V2',200,'V2: institution certif