INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-AD9C07CECC91EBD3D593','applied_research',NULL,'acatech Executive Committee elects Claudia Eckert as President of the German Academy of Science and Engineering - Fraunhofer AISEC','https://www.aisec.fraunhofer.de/en/media/press-releases/2025/acatech-executive-committee-elects-claudia-eckert-as-president-o.html',NULL,'Applied and Integrated Security',NULL,'Germany','Europe','official_research_institution',NULL,NULL,'2026-10-04T10:27:48.201Z','institutional_primary','en','© Bernd Müller / Fraunhofer AISEC Claudia Eckert, Director of Fraunhofer AISEC and Professor at the Technical University of Munich, takes over as Scientific President of acatech - the National Academy of Science and Engineering. After completing his four-year term of office, Jan Wörner will hand over the office of Scientific President of acatech - National Academy of Science and Engineering to Claudia Eckert on July 1, 2025 The professor at the Technical University of Munich and Director of Fraunhofer AISEC was unanimously elected by acatech''s Executive Committee. Claudia Eckert joins Co-President Thomas Weber: Together they embody the cooperation between science and industry on innovation issues. Siegfried Russwurm, member of the acatech Executive Board and former BDI President, was elected acatech Vice-President.','© Bernd Müller / Fraunhofer AISEC Claudia Eckert, Director of Fraunhofer AISEC and Professor at the Technical University of Munich, takes over as Scientific President of acatech - the National Academy of Science and Engineering. After completing his four-year term of office, Jan Wörner will hand over the office of Scientific President of acatech - National Academy of Science and Engineering to Claudia Eckert on July 1, 2025 The professor at the Technical University of Munich and Director of Fraunhofer AISEC was unanimously elected by acatech''s Executive Committee. Claudia Eckert joins Co-President Thomas Weber: Together they embody the cooperation between science and industry on innovation issues. Siegfried Russwurm, member of the acatech Executive Board and former BDI President, was elected acatech Vice-President.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://www.aisec.fraunhofer.de/en/media/press-releases/2025/acatech-executive-committee-elects-claudia-eckert-as-president-o.html',NULL,3,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','29b06a4a820351fe38270ef51714d477ecc30a0bad53b0e17899f12c6273bb77','ad9c07cecc91ebd3d5939010d8be7c183401ff92be64437a07500c1ec132a59f',1,1,1,1 FROM sources WHERE root_url='https://www.aisec.fraunhofer.de/en.html' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
