INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-113A175929EF9155AD22','applied_research',NULL,'Sovereign Cloud-Edge Services for Europe&#039;s Technological Independence - Fraunhofer AISEC','https://www.aisec.fraunhofer.de/en/media/press-releases/2026/sovereign-cloud-edge-services.html',NULL,'Applied and Integrated Security',NULL,'Germany','Europe','official_research_institution',NULL,NULL,'2026-10-04T10:27:48.974Z','institutional_primary','en','© Magnific AI U.S. tech giants dominate the cloud market. This threatens the technological sovereignty, data protection, and innovative capacity of European companies. In the »ApeiroRA« project, the Fraunhofer Institutes for Software and Systems Engineering (ISST) and for Applied and Integrated Security (AISEC) are supporting the software company SAP in securing Europe’s technological and economic independence in the cloud and edge sectors. The partners are developing an open-source blueprint for a European, vendor-neutral cloud-edge infrastructure that guarantees interoperability among different providers.','© Magnific AI U.S. tech giants dominate the cloud market. This threatens the technological sovereignty, data protection, and innovative capacity of European companies. In the »ApeiroRA« project, the Fraunhofer Institutes for Software and Systems Engineering (ISST) and for Applied and Integrated Security (AISEC) are supporting the software company SAP in securing Europe’s technological and economic independence in the cloud and edge sectors. The partners are developing an open-source blueprint for a European, vendor-neutral cloud-edge infrastructure that guarantees interoperability among different providers.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://www.aisec.fraunhofer.de/en/media/press-releases/2026/sovereign-cloud-edge-services.html',NULL,2,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','044f2d6a63fd600101e4e3a10f40b6ae6718e02737681f32eee1e83f8d5692b3','113a175929ef9155ad2236763fc376215655f9d940bdff8cb0a6a23a7310406e',1,1,1,1 FROM sources WHERE root_url='https://www.aisec.fraunhofer.de/en.html' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
