INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-F22F262943343D1DEF11','applied_research',NULL,'Collaboration - Fraunhofer FIT','https://www.fit.fraunhofer.de/en/business-areas/data-science-and-artificial-intelligence/process-mining/collaboration.html',NULL,'Applied Information Technology',NULL,'Germany','Europe','official_research_institution',NULL,NULL,'2026-10-04T10:28:19.948Z','institutional_primary','en','There has been an increasing awareness of the huge potential that process and data science provides for businesses, as witnessed by several success stories as published by the IEEE CIS Task Force on Process Mining . As a result, several software development companies have developed solutions that support and / or integrate process mining oriented analyses. Moreover, some software vendors provide dedicated process mining solutions. However, integration of state-of-the-art techniques, originating from process mining research, are often missing.','There has been an increasing awareness of the huge potential that process and data science provides for businesses, as witnessed by several success stories as published by the IEEE CIS Task Force on Process Mining . As a result, several software development companies have developed solutions that support and / or integrate process mining oriented analyses. Moreover, some software vendors provide dedicated process mining solutions. However, integration of state-of-the-art techniques, originating from process mining research, are often missing.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://www.fit.fraunhofer.de/en/business-areas/data-science-and-artificial-intelligence/process-mining/collaboration.html',NULL,2,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','cb6ef0da2501fbb0c441c75482e83d69558a3dbd0a2a0ccdaaea9f88bc7bfee2','f22f262943343d1def11304e0533dae35911a010b6922e45def8d40b9efc4ecf',1,1,1,1 FROM sources WHERE root_url='https://www.fit.fraunhofer.de/en.html' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
INSERT INTO document_search(document_id,search_text,updated_at) SELECT id,'collaboration - fraunhofer fit there has been an increasing awareness of the huge potential that process and data science provides for businesses as witnessed by several success stories as published by the ieee cis task force on process mining . as a result several software development companies have developed solutions that support and or integrate process mining oriented analyses. moreover some software vendors provide dedicated process mining solutions. however integration of state-of-the-art techniques originating from process mining research are often missing. applied research',CURRENT_TIMESTAMP FROM documents WHERE canonical_hash='f22f262943343d1def11304e0533dae35911a010b6922e45def8d40b9efc4ecf' ON CONFLICT(document_id) DO UPDATE SET search_text=excluded.search_text,updated_at=CURRENT_TIMESTAMP;
INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-CAD44F890DA83497E672','applied_research',NULL,'Data Management and Engineering - Fraunhofer FIT','https://www.fit.fraunhofer.de/en/business-areas/data-science-and-artificial-intelligence/data-management.html',NULL,'Applied Information Technology',NULL,'Germany','Europe','official_research_institution',NULL,NULL,'2026-10-04T10:28:17.888Z','institutional_primary','en','In many applications, management and integration of heterogeneous data is a major challenge. The data management research group develops scalable data management solutions for small and big data in different areas (life science healthcare, industry), which integrate data from various sources and make them available for data analysis. A sophisticated meta data management approach is applied to extract meta data from various sources, to enrich those with semantic annotations and to integrate them via semi-automatic matching.','In many applications, management and integration of heterogeneous data is a major challenge. The data management research group develops scalable data management solutions for small and big data in different areas (life science healthcare, industry), which integrate data from various sources and make them available for data analysis. A sophisticated meta data management approach is applied to extract meta data from various sources, to enrich those with semantic annotations and to integrate them via semi-automatic matching.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://www.fit.fraunhofer.de/en/business-areas/data-science-and-artificial-intelligence/data-management.html',NULL,3,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','b739bd180d0472d01eec1a9b35c0a1bde08ae7c90b0ee13a60c67bf2718decd0','cad44f890da83497e672a724782d8223faca779085fbab85b6774c937856822e',1,1,1,1 FROM sources WHERE root_url='https://www.fit.fraunhofer.de/en.html' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
