INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-537E16CA927B6A731339','applied_research',NULL,'FAIR Data and Distributed Analytics - Fraunhofer FIT','https://www.fit.fraunhofer.de/en/business-areas/data-science-and-artificial-intelligence/fair-data-and-distributed-analytics.html',NULL,'Applied Information Technology',NULL,'Germany','Europe','official_research_institution',NULL,NULL,'2026-10-04T10:28:18.013Z','institutional_primary','en','We advance the practical implementation of FAIR principles (Findable, Accessible, Interoperable, Reusable) through comprehensive data infrastructures and knowledge management systems. Our work encompasses FAIR Digital Objects (FDOs), research data infrastructure development, knowledge graphs, semantic technologies, persistent identifiers (PIDs), and data sovereignty frameworks.','We advance the practical implementation of FAIR principles (Findable, Accessible, Interoperable, Reusable) through comprehensive data infrastructures and knowledge management systems. Our work encompasses FAIR Digital Objects (FDOs), research data infrastructure development, knowledge graphs, semantic technologies, persistent identifiers (PIDs), and data sovereignty frameworks.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://www.fit.fraunhofer.de/en/business-areas/data-science-and-artificial-intelligence/fair-data-and-distributed-analytics.html',NULL,2,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','8e85a888bd69e2eba19da58759aef4244c2adb511a49c531b50f3adc09e09eb9','537e16ca927b6a7313391b24e2274b2bba352ebd7fcbdbbd24024ef5e8afbb73',1,1,1,1 FROM sources WHERE root_url='https://www.fit.fraunhofer.de/en.html' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
