INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-294258B4941C9ED0234C','applied_research',NULL,'FAIR Digital Objects Manager - Fraunhofer FIT','https://www.fit.fraunhofer.de/en/business-areas/data-science-and-artificial-intelligence/fair-data-and-distributed-analytics/FAIR-Digital-Objects-Manager.html',NULL,'Applied Information Technology',NULL,'Germany','Europe','official_research_institution',NULL,NULL,'2026-10-04T10:28:18.015Z','institutional_primary','en','The FDO Manager as part of the NFDI4DS represents one of the initial implementations of the FDO in practice, which adheres to the FDO specifications while offering a robust minimum viable solution. The manager ensures the necessary metadata and a persistent identifier accompany each artefact. To fully comply with the FDO specifications, the manager ensures that the metadata is temporarily stored in a dedicated registry managed by Fraunhofer FIT, separate from the digital objects themselves. Furthermore, the FDO Manager will handle the recording and storage of FDO records in a distinct registry, which is a key requirement in the FDO specifications.','The FDO Manager as part of the NFDI4DS represents one of the initial implementations of the FDO in practice, which adheres to the FDO specifications while offering a robust minimum viable solution. The manager ensures the necessary metadata and a persistent identifier accompany each artefact. To fully comply with the FDO specifications, the manager ensures that the metadata is temporarily stored in a dedicated registry managed by Fraunhofer FIT, separate from the digital objects themselves. Furthermore, the FDO Manager will handle the recording and storage of FDO records in a distinct registry, which is a key requirement in the FDO specifications.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://www.fit.fraunhofer.de/en/business-areas/data-science-and-artificial-intelligence/fair-data-and-distributed-analytics/FAIR-Digital-Objects-Manager.html',NULL,2,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','9a75fab9af3fe08f8797966c4003a8cdcffcc2f0b5583b77f9c5c2926ec722df','294258b4941c9ed0234c58106ad39f5d16deb2a8888a6a28a25e80ddda996172',1,1,1,1 FROM sources WHERE root_url='https://www.fit.fraunhofer.de/en.html' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
