INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-CB641F68B171657382FB','applied_research',NULL,'Process Mining - Fraunhofer FIT','https://www.fit.fraunhofer.de/en/business-areas/data-science-and-artificial-intelligence/process-mining.html',NULL,'Applied Information Technology',NULL,'Germany','Europe','official_research_institution',NULL,NULL,'2026-10-04T10:28:18.005Z','institutional_primary','en','Modern information systems track the execution of (business) processes in their underlying databases. These vast amounts of operational event data are a valuable source to further enhance and improve these processes. The group of process mining focuses on the application of advanced process mining algorithms in practice. Additionally, the group actively contributes to cutting-edge research in the field. The group works on multiple projects including large research projects, the application of process mining at industrial partners and the development of various process mining software solutions.','Modern information systems track the execution of (business) processes in their underlying databases. These vast amounts of operational event data are a valuable source to further enhance and improve these processes. The group of process mining focuses on the application of advanced process mining algorithms in practice. Additionally, the group actively contributes to cutting-edge research in the field. The group works on multiple projects including large research projects, the application of process mining at industrial partners and the development of various process mining software solutions.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://www.fit.fraunhofer.de/en/business-areas/data-science-and-artificial-intelligence/process-mining.html',NULL,2,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','d75aa9862a4f23236f83d59600aeb2a1148f507d91f714a6c43ab7d06f53ff53','cb641f68b171657382fb458966575ef6083e76634cb7a5c2facfbe8a6e09f9d0',1,1,1,1 FROM sources WHERE root_url='https://www.fit.fraunhofer.de/en.html' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
