INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-3CE3DAD2D874658C980F','applied_research',NULL,'Research - Fraunhofer FIT','https://www.fit.fraunhofer.de/en/business-areas/data-science-and-artificial-intelligence/process-mining/research.html',NULL,'Applied Information Technology',NULL,'Germany','Europe','official_research_institution',NULL,NULL,'2026-10-04T10:28:15.880Z','institutional_primary','en','We aim to develop novel techniques, methods and tools in the process mining domain. The tight integration of the discipline of Fraunhofer FIT’s Process Mining group with the Process and Data Science chair of the RWTH Aachen University , allows for a unique knowledge exchange between top researchers in the field. Furthermore, the close cooperation of our group with industry allows for the identification of problems and corresponding solutions that are of actual business value.','We aim to develop novel techniques, methods and tools in the process mining domain. The tight integration of the discipline of Fraunhofer FIT’s Process Mining group with the Process and Data Science chair of the RWTH Aachen University , allows for a unique knowledge exchange between top researchers in the field. Furthermore, the close cooperation of our group with industry allows for the identification of problems and corresponding solutions that are of actual business value.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://www.fit.fraunhofer.de/en/business-areas/data-science-and-artificial-intelligence/process-mining/research.html',NULL,3,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','9dce16df8c1589c222048feb5a1ef99cc35d15bb129ee16b94f4555fb39294b2','3ce3dad2d874658c980fda092f7e0d3c9d90f0b20867ecfebbf68b4f1abec401',1,1,1,1 FROM sources WHERE root_url='https://www.fit.fraunhofer.de/en.html' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
