INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-E0DF856A3692F350258B','applied_research',NULL,'Research structure expansion of photonics - Fraunhofer IOF','https://www.iof.fraunhofer.de/en/projects/nlp.html',NULL,'Applied Optics and Precision Engineering',NULL,'Germany','Europe','official_research_institution',NULL,NULL,'2026-10-04T10:28:17.791Z','institutional_primary','en','With the "National Laboratory for Photonic Science and Technology" (NLP), the Fraunhofer Institute for Applied Optics and Precision Engineering IOF, the Fraunhofer Institute for Telecommunications, Heinrich Hertz Institute, HHI and the Max Planck Institute for the Science of Light MPL have developed a concept for a new, innovative research infrastructure for the expansion of photonics in Germany and submitted it to the BMBF for evaluation as part of the "Procedure for Prioritizing New Research Infrastructures".','With the "National Laboratory for Photonic Science and Technology" (NLP), the Fraunhofer Institute for Applied Optics and Precision Engineering IOF, the Fraunhofer Institute for Telecommunications, Heinrich Hertz Institute, HHI and the Max Planck Institute for the Science of Light MPL have developed a concept for a new, innovative research infrastructure for the expansion of photonics in Germany and submitted it to the BMBF for evaluation as part of the "Procedure for Prioritizing New Research Infrastructures".',NULL,N