INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-4B029BCF20C235CE9188','applied_research',NULL,'XPS reveals the surface chemistry of bio-based hybrid materials - Fraunhofer IAP','https://www.iap.fraunhofer.de/en/press_releases/2026/XPS-reveals-the-surface-chemistry-of-bio-based-hybrid-materials.html',NULL,'Applied Polymer Research',NULL,'Germany','Europe','official_research_institution','2026-09-08T22:00:00Z',NULL,'2026-10-04T10:28:26.437Z','institutional_primary','en','Just a few atomic layers at the surface can strongly influence how effectively a material binds pollutants from water or how efficiently a photocatalyst responds to light. Researchers at the Fraunhofer Institute for Applied Polymer Research IAP use X-ray photoelectron spectroscopy (XPS) to investigate the chemical states and interactions at the surfaces and interfaces of bio-based carbon materials and organic-inorganic hybrid materials. Their insights can support the targeted development of functional materials for future industrial applications.','Just a few atomic layers at the surface can strongly influence how effectively a material binds pollutants from water or how efficiently a photocatalyst responds to light. Researchers at the Fraunhofer Institute for Applied Polymer Research IAP use X-ray photoelectron spectroscopy (XPS) to investigate the chemical states and interactions at the surfaces and interfaces of bio-based carbon materials and organic-inorganic hybrid materials. Their insights can support the targeted development of functional materials for future industrial applications.',NULL,NULL,NULL,NULL,NULL,'10.1021/acsomega.4c09171','10.1021/acsomega.4c09171',NULL,'free','primary','not_applicable',NULL,NULL,'https://www.iap.fraunhofer.de/en/press_releases/2026/XPS-reveals-the-surface-chemistry-of-bio-based-hybrid-materials.html',NULL,2,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','5ceb171dbc074ae57bec5e3a4397c5b6726ba81379bdac5ecf04704375a94b14','4b029bcf20c235ce9188586143991fd3fd34c2c7210e526ca6bea52c7c3ba18d',1,1,1,1 FROM sources WHERE root_url='https://www.iap.fraunhofer.de/en.html' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
