INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-A0CD43A9C1EE6347BB86','applied_research',NULL,'Fraunhofer IAF expands technology capabilities for chiplet innovations within the APECS pilot line - Fraunhofer IAF','https://www.iaf.fraunhofer.de/en/media-library/press-releases/fraunhofer-iaf-expands-technology-capabilities-for-chiplet-innovations.html',NULL,'Applied Solid State Physics',NULL,'Germany','Europe','official_research_institution','2024-12-17T07:00:00Z',NULL,'2026-10-04T10:28:48.352Z','institutional_primary','en','Fraunhofer IAF is expanding its technological capabilities in the field of III-V compound semiconductors, making a valuable contribution to the development of the APECS pilot line within the framework of the EU Chips Act. The Baden-Württemberg Ministry of Economic Affairs, Labour and Tourism is contributing 4.35 million euros to the funding. On 16 December 2024, State Secretary for Economic Affairs Dr. Patrick Rapp symbolically handed over a cheque for the funding amount to the institute’s directors.','Fraunhofer IAF is expanding its technological capabilities in the field of III-V compound semiconductors, making a valuable contribution to the development of the APECS pilot line within the framework of the EU Chips Act. The Baden-Württemberg Ministry of Economic Affairs, Labour and Tourism is contributing 4.35 million euros to the funding. On 16 December 2024, State Secretary for Economic Affairs Dr. Patrick Rapp symbolically handed over a cheque for the funding amount to the institute’s directors.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://www.iaf.fraunhofer.de/en/media-library/press-releases/fraunhofer-iaf-expands-technology-capabilities-for-chiplet-innovations.html',NULL,3,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','d9076b1ad4b18d39f1b78a47f192bd33ba6720a292137df3a9d5d038fb012160','a0cd43a9c1ee6347bb869082f8bedcf0a2dccf95215c705434a75ba869695fa9',1,1,1,1 FROM sources WHERE root_url='https://www.iaf.fraunhofer.de/en.html' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
