INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-7B64587B307EC08309FB','applied_research',NULL,'Digitalization in battery cell production','https://www.ffb.fraunhofer.de/en/publications/White_papers_environment_reports_studies/Digitalization_in_battery_cell_production.html',NULL,'Battery Cell Production FFB',NULL,'Germany','Europe','official_research_institution','2024-04-17T22:00:00Z',NULL,'2026-10-04T10:28:49.144Z','institutional_primary','en','The white paper by Fraunhofer FFB and Accenture focuses on digital solutions. For the study, 143 battery and digitalisation experts from mainly European and North American companies were surveyed in two stages. Firstly, the experts identified particularly effective use cases for digital solutions in battery production. These cases were integrated into a model of a battery factory with a capacity of 40 gigawatt hours, which the experts used to calculate and assess potential savings for each use case and production step.','The white paper by Fraunhofer FFB and Accenture focuses on digital solutions. For the study, 143 battery and digitalisation experts from mainly European and North American companies were surveyed in two stages. Firstly, the experts identified particularly effective use cases for digital solutions in battery production. These cases were integrated into a model of a battery factory with a capacity of 40 gigawatt hours, which the experts used to calculate and assess potential savings for each use case and production step.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://www.ffb.fraunhofer.de/en/publications/White_papers_environment_reports_studies/Digitalization_in_battery_cell_production.html',NULL,5,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','062ce9c5cb0230cd8d50fc1eb4787174213a0872859add0e9809e095246a51a8','7b64587b307ec08309fbdc7079ed92e9be0be0102405aa0eebc6373309b980fa',1,1,1,1 FROM sources WHERE root_url='https://www.ffb.fraunhofer.de/en.html' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
INSERT INTO document_search(document_id,search_text,updated_at) SELECT id,'digitalization in battery cell production the white paper by fraunhofer ffb and accenture focuses on digital solutions. for the study 143 battery and digitalisation experts from mainly european and north american companies were surveyed in two stages. firstly the experts identified particularly effective use cases for digital solutions in battery production. these cases were integrated into a model of a battery factory with a capacity of 40 gigawatt hours which the experts used to calculate and assess potential savings for each use case and production step. applied research',CURRENT_TIMESTAMP FROM documents WHERE canonical_hash='7b64587b307ec08309fbdc7079ed92e9be0be0102405aa0eebc6373309b980fa' ON CONFLICT(document_id) DO UPDATE SET search_text=excluded.search_text,updated_at=CURRENT_TIMESTAMP;
