INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-77C7720AFC3F222238AF','applied_research',NULL,'Environmental report on sodium-ion batteries','https://www.ffb.fraunhofer.de/en/publications/White_papers_environment_reports_studies/Environmental_report_on_sodium-ion_batteries.html',NULL,'Battery Cell Production FFB',NULL,'Germany','Europe','official_research_institution','2023-10-05T22:00:00Z',NULL,'2026-10-04T10:28:49.261Z','institutional_primary','en','A new Fraunhofer FFB environment report deals with sodium-ion batteries as an alternative battery technology. The researchers analyse the technological properties of the battery as well as the activities in research and industry relating to this technology - from material production and cell production to the emergence of user markets. The environment report was produced as part of the overall &#034;FoFeBat&#034; project funded by the BMBF.','A new Fraunhofer FFB environment report deals with sodium-ion batteries as an alternative battery technology. The researchers analyse the technological properties of the battery as well as the activities in research and industry relating to this technology - from material production and cell production to the emergence of user markets. The environment report was produced as part of the overall &#034;FoFeBat&#034; project funded by the BMBF.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable'