INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-07BA078D6358F32A9946','applied_research',NULL,'Biomedical Data & Bioethics','https://www.ibmt.fraunhofer.de/en/ibmt-core-competences/ibmt-stem-cell-cryo-technology/ibmt-stemcell-technology-cryo-technology-biomedical-data-bioethics.html',NULL,'Biomedical Engineering',NULL,'Germany','Europe','official_research_institution',NULL,NULL,'2026-10-04T10:28:56.186Z','institutional_primary','en','The Biomedical Data & Bioethics Group engages in the development of systems to manage and analyze a wide spectrum of data, from basic biomedical research to digital applications for healthcare and clinical research. The group focuses on biomedical data as a starting resource for basic and applied research, through the transformation and processing of biomedical data to generate new knowledge and to develop innovative tools that enable effective re-utilization of data and information. Working with sensitive personal data, such as genetic data, in conjunction with machine learning (ML) or artificial intelligence (AI) challenges the boundaries of existing ethical frameworks. Consequently, the group is actively developing ethical tools and mechanisms to deal with these challenges, such that research and development can continue to advance.','The Biomedical Data & Bioethics Group engages in the development of systems to manage and analyze a wide spectrum of data, from basic biomedical research to digital applications for healthcare and clinical research. The group focuses on biomedical data as a starting resource for basic and applied research, through the transformation and processing of biomedical data to generate new knowledge and to develop innovative tools that enable effective re-utilization of data and information. Working with sensitive personal data, such as genetic data, in conjunction with machine learning (ML) or artificial intelligence (AI) challenges the boundaries of existing ethical frameworks. Consequently, the group is actively developing ethical tools and mechanisms to deal with these challenges, such that research and development can continue to advance.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://www.ibmt.fraunhofer.de/en/ibmt-core-competences/ibmt-stem-cell-cryo-technology/ibmt-stemcell-technology-cryo-technology-biomedical-data-bioethics.html',NULL,3,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','e704ffc921bec9b6c18c52832428bf303e23a521f8115e779ff6dbf97ee0984b','07ba078d6358f32a9946e18b105a61373cf9f75272742855ddc10f59ece192ba',1,1,1,1 FROM sources WHERE root_url='https://www.ibmt.fraunhofer.de/en.html' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
