INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-7D139A6BA03FB89D2AC6','applied_research',NULL,'Advanced Analytics Technology Platform - Fraunhofer IZI','https://www.izi.fraunhofer.de/en/central-facilities/advanced-analytics-technology-platform.html',NULL,'Cell Therapy and Immunology',NULL,'Germany','Europe','official_research_institution',NULL,NULL,'2026-10-04T10:30:20.286Z','institutional_primary','en','The Advanced Analytics Technology Platform bundles existing competencies at Fraunhofer IZI in the fields of chromatography and mass spectrometry, flow cytometry, microscopy, sequencing as well as bioinformatics and machine learning. Using the latest technologies and expertise, the platform enables comprehensive analyses from a single source. Assays can be developed under BSL-2 conditions on a small scale or proof-of-concept studies can be performed according to customer-specific requirements. The subdivisions of the platform work together in an integrative manner. The technology platform supports partners and customers in the design and execution of experiments, the selection and use of suitable equipment, and multi-modal data evaluation.','The Advanced Analytics Technology Platform bundles existing competencies at Fraunhofer IZI in the fields of chromatography and mass spectrometry, flow cytometry, microscopy, sequencing as well as bioinformatics and machine learning. Using the latest technologies and expertise, the platform enables comprehensive analyses from a single source. Assays can be developed under BSL-2 conditions on a small scale or proof-of-concept studies can be performed according to customer-specific requirements. The subdivisions of the platform work together in an integrative manner. The technology platform supports partners and customers in the design and execution of experiments, the selection and use of suitable equipment, and multi-modal data evaluation.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://www.izi.fraunhofer.de/en/central-facilities/advanced-analytics-technology-platform.html',NULL,3,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','7a26e94a5ad0bbcdc9cbf16d782e1b0c1dc31cbb8364d5720b08e001bc7c12fb','7d139a6ba03fb89d2ac6a3f332a80becaeda864fbe3806371e2d855b8bac80c6',1,1,1,1 FROM sources WHERE root_url='https://www.izi.fraunhofer.de/en.html' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
