INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-D2F7DDA909A0D60369B1','applied_research',NULL,'Binding analytics - Fraunhofer IZI','https://www.izi.fraunhofer.de/en/central-facilities/advanced-analytics-technology-platform/analytics.html',NULL,'Cell Therapy and Immunology',NULL,'Germany','Europe','official_research_institution',NULL,NULL,'2026-10-04T10:30:20.395Z','institutional_primary','en','The biophysical analytics laboratory focuses on the characterisation of interactions between biomolecules (proteins, peptides, nucleic acids and small molecules). The laboratory has a number of instruments which are specifically used depending on the question examined to determine bond strength (affinity), bond kinetics, as well as the thermodynamics of bonds. The appropriate methods are selected in cooperation with the project partners. In addition, the laboratory has the suitable expertise and equipment for quantifying biomolecules on the basis of various immunoassays (such as ELISA) as well as time-resolved fluorescence. The laboratory is GLP (Good Laboratory Practice) certified, so that customer-specific applications can be developed and validated, both for pure research projects and for work processes in a regulatory sphere.','The biophysical analytics laboratory focuses on the characterisation of interactions between biomolecules (proteins, peptides, nucleic acids and small molecules). The laboratory has a number of instruments which are specifically used depending on the question examined to determine bond strength (affinity), bond kinetics, as well as the thermodynamics of bonds. The appropriate methods are selected in cooperation with the project partners. In addition, the laboratory has the suitable expertise and equipment for quantifying biomolecules on the basis of various immunoassays (such as ELISA) as well as time-resolved fluorescence. The laboratory is GLP (Good Laboratory Practice) certified, so that customer-specific applications can be developed and validated, both for pure research projects and for work processes in a regulatory sphere.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://www.izi.fraunhofer.de/en/central-facilities/advanced-analytics-technology-platform/analytics.html',NULL,3,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','703aa43eaa3b281192262be74c29747a4c06271104c513a42507837ac9f39a31','d2f7dda909a0d60369b1d0d81215f15e2362d96925695fc573881b93fcf2864d',1,1,1,1 FROM sources WHERE root_url='https://www.izi.fraunhofer.de/en.html' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
