INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-B30F43A3A5AD8EFEC91E','applied_research',NULL,'Fraunhofer IZI research project nominated for &#034;HUGO JUNKERS PRIZE for Research and Innovation from Saxony-Anhalt&#034; - Fraunhofer IZI','https://www.izi.fraunhofer.de/en/press/press-releases/fraunhofer-izi-research-project-nominated-for-hugo-junkers-prize-for-research-and-innovation-from-saxony-anhalt.html',NULL,'Cell Therapy and Immunology',NULL,'Germany','Europe','official_research_institution',NULL,NULL,'2026-10-04T10:30:20.862Z','institutional_primary','en','The Fraunhofer Institute for Cell Therapy and Immunology IZI conducts research on neurodegenerative and inflammatory diseases at its Halle (Saale) site. With their approach of using endogenous retroviruses as target structures for new therapies against neurological diseases, the scientists qualified for the finals of this year&#039;s HUGO JUNKERS AWARD in the category &#034;Most Innovative Basic Research Projects&#034;.','The Fraunhofer Institute for Cell Therapy and Immunology IZI conducts research on neurodegenerative and inflammatory diseases at its Halle (Saale) site. With their approach of using endogenous retroviruses as target structures for new therapies against neurological diseases, the scientists qualified for the finals of this year&#039;s HUGO JUNKERS AWARD in the category &#034;Most Innovative Basic Research Projects&#034;.',NUL