INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-0F146D3AF802358A1967','applied_research',NULL,'Microscopy - Fraunhofer IZI','https://www.izi.fraunhofer.de/en/central-facilities/advanced-analytics-technology-platform/microscopy.html',NULL,'Cell Therapy and Immunology',NULL,'Germany','Europe','official_research_institution',NULL,NULL,'2026-10-04T10:30:20.967Z','institutional_primary','en','© Fraunhofer IZI Phenotyping biological samples using multiple imaging methods forms a core competence of preclinical research. This enables thorough depiction, from the smallest structures (cell organelles) right through to entire organ systems, both in spatial and temporal resolution (4D). Fraunhofer IZI has access to a comprehensive, state-of-the-art equipment pool that enables the acquisition and evaluation of various (also correlative) image data. Partners and customers are advised on biological, technical and economic matters and supported in carrying out and evaluating experiments. Furthermore, experimental procedures and equipment can be used, adapted and developed.','© Fraunhofer IZI Phenotyping biological samples using multiple imaging methods forms a core competence of preclinical research. This enables thorough depiction, from the smallest structures (cell organelles) right through to entire organ systems, both in spatial and temporal resolution (4D). Fraunhofer IZI has access to a comprehensive, state-of-the-art equipment pool that enables the acquisition and evaluation of various (also correlative) image data. Partners and customers are advised on biological, technical and economic matters and supported in carrying out and evaluating experiments. Furthermore, experimental procedures and equipment can be used, adapted and developed.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://www.izi.fraunhofer.de/en/central-facilities/advanced-analytics-technology-platform/microscopy.html',NULL,3,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','05cc9c9aba6e3620c0b76f4dcb192c40bdf883d7c3c80f4eed668225de8821e4','0f146d3af802358a1967f800a31f9d2cfabd13cec22fc0f2e31b9b536a511de9',1,1,1,1 FROM sources WHERE root_url='https://www.izi.fraunhofer.de/en.html' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
