INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-B2CEE60BDCDD0BA084F8','applied_research',NULL,'Patented Fraunhofer IZI technology facilitates specific Dengue virus diagnostics - Fraunhofer IZI','https://www.izi.fraunhofer.de/en/press/press-releases/patented-fraunhofer-izi-technology-facilitates-specific-dengue-virus-diagnostics.html',NULL,'Cell Therapy and Immunology',NULL,'Germany','Europe','official_research_institution',NULL,NULL,'2026-10-04T10:30:21.110Z','institutional_primary','en','A new technology developed by the Fraunhofer Institute for Cell Therapy and Immunology (IZI) facilitates a specific, sensitive diagnosis of the Dengue virus. The patented procedure has been licensed to two companies and corresponding antibody tests are now available on the market. As a result, both the four different Dengue virus serotypes can be differentiated and also the Dengue virus itself can be distinguished from other closely related flaviviruses, which include the yellow fever virus and tick-borne encephalitis virus, in addition to the Zika virus and the West Nile virus. Moreover, work is already underway to adapt the procedure to the SARS-CoV-2 virus and the West Nile virus.','A new technology developed by the Fraunhofer Institute for Cell Therapy and Immunology (IZI) facilitates a specific, sensitive diagnosis of the Dengue virus. The patented procedure has been licensed to two companies and corresponding antibody tests are now available on the market. As a result, both the four different Dengue virus serotypes can be differentiated and also the Dengue virus itself can be distinguished from other closely related flaviviruses, which include the yellow fever virus and tick-borne encephalitis virus, in addition to the Zika virus and the West Nile virus. Moreover, work is already underway to adapt the procedure to the SARS-CoV-2 virus and the West Nile virus.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://www.izi.fraunhofer.de/en/press/press-releases/patented-fraunhofer-izi-technology-facilitates-specific-dengue-virus-diagnostics.html',NULL,3,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','77bdfa6d01c7b968927c54b7967edfca3a908eee312ef161e1550d43e6f5b83d','b2cee60bdcdd0ba084f82312962f6cdfd2d32aa9f7cd96eb45cd981eb07e07d2',1,1,1,1 FROM sources WHERE root_url='https://www.izi.fraunhofer.de/en.html' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
INSERT INTO document_search(document_id,search_text,updated_at) SELECT id,'patented fraunhofer izi technology facilitates specific dengue virus diagnostics - fraunhofer izi a new technology developed by the fraunhofer institute for cell therapy and immunology izi facilitates a specific sensitive diagnosis of the dengue virus. the patented procedure has been licensed to two companies and corresponding antibody tests are now available on the market. as a result both the four different dengue virus serotypes can be differentiated and also the dengue virus itself can be distinguished from other closely related flaviviruses which include the yellow fever virus and tick-borne encephalitis virus in addition to the zika virus and the west nile virus. moreover work is already underway to adapt the procedure to the sars-cov-2 virus and the west nile virus. applied research',CURRENT_TIMESTAMP FROM documents WHERE canonical_hash='b2cee60bdcdd0ba084f82312962f6cdfd2d32aa9f7cd96eb45cd981eb07e07d2' ON CONFLICT(document_id) DO UPDATE SET search_text=excluded.search_text,updated_at=CURRENT_TIMESTAMP;
