INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-3A8DCA4A98724D794DDA','applied_research',NULL,'Sequencing - Fraunhofer IZI','https://www.izi.fraunhofer.de/en/central-facilities/advanced-analytics-technology-platform/sequencing.html',NULL,'Cell Therapy and Immunology',NULL,'Germany','Europe','official_research_institution',NULL,NULL,'2026-10-04T10:30:20.963Z','institutional_primary','en','© Fraunhofer IZI The services offered by the Next-Generation Diagnostics Unit include joint experimental planning of the individual sequencing project, isolation and quality control of the starting samples (usually DNA or RNA) as well as sample preparation and performance of the actual sequencing. Many standard methods are validated in our laboratory and are performed according to SOP. However, we are also happy to implement individually adapted or new protocols with you.','© Fraunhofer IZI The services offered by the Next-Generation Diagnostics Unit include joint experimental planning of the individual sequencing project, isolation and quality control of the starting samples (usually DNA or RNA) as well as sample preparation and performance of the actual sequencing. Many standard methods are validated in our laboratory and are performed according to SOP. However, we are also happy to implement individually adapted or new protocols with you.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://www.izi.fraunhofer.de/en/central-facilities/advanced-analytics-technology-platform/sequencing.html',NULL,3,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','509ae41d5d02176bf5239bf691b79ed22450e20636776845628bfe0bd2e6119a','3a8dca4a98724d794ddac3f0315da671f0ac89a975be81753372a865b2d5f35f',1,1,1,1 FROM sources WHERE root_url='https://www.izi.fraunhofer.de/en.html' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
