INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-06F8FDA3115E8D11086A','applied_research',NULL,'60 years of military science research in Wachtberg - Fraunhofer FKIE','https://www.fkie.fraunhofer.de/en/press-releases/60-years-of-military-science-research-in-wachtberg.html',NULL,'Communication, Information Processing and Ergonomics',NULL,'Germany','Europe','official_research_institution','2023-09-11T22:00:00Z',NULL,'2026-10-04T10:32:01.704Z','institutional_primary','en','Securing the future viability and technological innovation of the German Armed Forces — these core tasks are embedded in the military science research carried out at the Wachtberg office in North Rhine-Westphalia. Fraunhofer FKIE has had a number of different guises over the years: it started out as FFM, FAT and IFE, was then one of three institutes incorporated into FGAN, finally becoming known as Fraunhofer FKIE since 2009. For 60 years now, its scientists have been conducting research into the defense and security of Germany and its alliance partners.','Securing the future viability and technological innovation of the German Armed Forces — these core tasks are embedded in the military science research carried out at the Wachtberg office in North Rhine-Westphalia. Fraunhofer FKIE has had a number of different guises over the years: it started out as FFM, FAT and IFE, was then one of three institutes incorporated into FGAN, finally becoming known as Fraunhofer FKIE since 2009. For 60 years now, its scientists have been conducting research into the defense and security of Germany and its alliance partners.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://www.fkie.fraunhofer.de/en/press-releases/60-years-of-military-science-research-in-wachtberg.html',NULL,2,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','c23b563c1d609b0a8b1f7053eba7e586635186ff7acb0fcd4da7f4f23eb96221','06f8fda3115e8d11086ad4c98dd5917c89167ffdc96f43669c0c84ddc390e75b',1,1,1,1 FROM sources WHERE root_url='https://www.fkie.fraunhofer.de/en.html' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
