INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-2939AF7CA78BF1DF2898','applied_research',NULL,'A-DRZ project launch - Fraunhofer FKIE','https://www.fkie.fraunhofer.de/en/press-releases/a-drz_project_launch.html',NULL,'Communication, Information Processing and Ergonomics',NULL,'Germany','Europe','official_research_institution','2018-11-12T23:00:00Z',NULL,'2026-10-04T10:32:02.194Z','institutional_primary','en','The Fraunhofer Institute for Communication, Information Processing and Ergonomics FKIE is one of 13 partners from the fields of emergency response, research and industry involved in the establishment of the German Rescue Robotics Center (A-DRZ) in Dortmund. The project, funded with 11.9 million euros from the Federal Ministry of Education and Research (BMBF), will officially kick off on 6 December. The mission of the new center is to promote the use of robots in rescue scenarios that pose excessive risks to emergency personnel.','The Fraunhofer Institute for Communication, Information Processing and Ergonomics FKIE is one of 13 partners from the fields of emergency response, research and industry involved in the establishment of the German Rescue Robotics Center (A-DRZ) in Dortmund. The project, funded with 11.9 million euros from the Federal Ministry of Education and Research (BMBF), will officially kick off on 6 December. The mission of the new center is to promote the use of robots in rescue scenarios that pose excessive risks to emergency personnel.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://www.fkie.fraunhofer.de/en/press-releases/a-drz_project_launch.html',NULL,1,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','f9fc686e8c30cc7b39e0fd1e25dac173c7007d0b6ffff39d5ede28b356aa7b12','2939af7ca78bf1df2898d3f36f920b9cea58d779f7ca933d421ff62c63e528e8',1,1,1,1 FROM sources WHERE root_url='https://www.fkie.fraunhofer.de/en.html' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
