INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-B8E97C7942244F88B962','applied_research',NULL,'Robot with LiDAR Laser explores danger zones - Fraunhofer FKIE','https://www.fkie.fraunhofer.de/en/press-releases/Virtual-3D-environment_research-news_01-2025.html',NULL,'Communication, Information Processing and Ergonomics',NULL,'Germany','Europe','official_research_institution','2025-01-02T10:00:00Z',NULL,'2026-10-04T10:32:01.840Z','institutional_primary','en','Robot systems explore unfamiliar terrain, buildings or danger zones with cameras. In the 3D-InAus project, researchers from the Fraunhofer Institute for Communication, Information Processing and Ergonomics FKIE are using a LiDAR laser on a mobile robot, emitting laser pulses to measure distances. The results are used to produce geometrically accurate 3D environments.','Robot systems explore unfamiliar terrain, buildings or danger zones with cameras. In the 3D-InAus project, researchers from the Fraunhofer Institute for Communication, Information Processing and Ergonomics FKIE are using a LiDAR laser on a mobile robot, emitting laser pulses to measure distances. The results are used to produce geometrically accurate 3D environments.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://www.fkie.fraunhofer.de/en/press-releases/Virtual-3D-environment_research-news_01-2025.html',NULL,2,'B','V2',200,'V2: institut