INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-930741419A8C58DFBBB6','applied_research',NULL,'Technology Forum 2026 - Fraunhofer FKIE','https://www.fkie.fraunhofer.de/en/press-releases/techforum-2026.html',NULL,'Communication, Information Processing and Ergonomics',NULL,'Germany','Europe','official_research_institution','2026-06-18T10:06:00Z',NULL,'2026-10-04T10:32:02.074Z','institutional_primary','en','“People and Technology – Collaborative Research and Innovation”—the title of the 7th Technology Forum—embodied both the Fraunhofer FKIE program and its practical application. Over the course of two days, the institute demonstrated on its campus in Wachtberg what is possible when researchers and users work together rather than side by side—with 23 exhibits, high-caliber keynote presentations, and a panel discussion that did not shy away from uncomfortable questions, as well as through the intensive personal exchange that has made this format so special for all participants for many years.','“People and Technology – Collaborative Research and Innovation”—the title of the 7th Technology Forum—embodied both the Fraunhofer FKIE program and its practical application. Over the course of two days, the institute demonstrated on its campus in Wachtberg what is possible when researchers and users work together rather than side by side—with 23 exhibits, high-caliber keynote presentations, and a panel discussion that did not shy away from uncomfortable questions, as well as through the intensive personal exchange that has made this format so special for all participants for many years.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://www.fkie.fraunhofer.de/en/press-releases/techforum-2026.html',NULL,2,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','84b2bac3872bd949a0e6e591a4194f7fba8ecd5eed9f7642212d4e5ca4786ad3','930741419a8c58dfbbb6226772ecfbef13e0ac62e9f57ec753919478c785359b',1,1,1,1 FROM sources WHERE root_url='https://www.fkie.fraunhofer.de/en.html' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
