INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-8783B6DC4AF17BF234A5','applied_research',NULL,'Fraunhofer technology trialed under real-world conditions - Fraunhofer IGD','https://www.igd.fraunhofer.de/en/media-center/customer-magazine/2020/visualisierungen-beschleunigen-den-glasfaserausbau.html',NULL,'Computer Graphics Research',NULL,'Germany','Europe','official_research_institution',NULL,NULL,'2026-10-04T10:32:10.024Z','institutional_primary','en','Fraunhofer IGD has developed a software solution that further automates the planning process for the roll-out of fiber-optic broadband. Fibre3D enables Deutsche Telekom to submit applications to local government agencies without the need for costly and time-consuming site visits. This accelerates the approval process, ensuring there are no delays to the expansion of Germany’s fiber-optic infrastructure. The software has now successfully completed a trial under real-world conditions.','Fraunhofer IGD has developed a software solution that further automates the planning process for the roll-out of fiber-optic broadband. Fibre3D enables Deutsche Telekom to submit applications to local government agencies without the need for costly and time-consuming site visits. This accelerates the approval process, ensuring there are no delays to the expansion of Germany’s fiber-optic infrastructure. The software has now successfully completed a trial under real-world conditions.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://www.igd.fraunhofer.de/en/media-center/customer-magazine/2020/visualisierungen-beschleunigen-den-glasfaserausbau.html',NULL,4,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','e9ef602e7f451054cbf81b0fe6d28c1e857f9f2c52b728f5ff93e3742d0b4429','8783b6dc4af17bf234a5d240a4d4a1f6f7fca87017219bc7647d20c7ae220d6c',1,1,1,1 FROM sources WHERE root_url='https://www.igd.fraunhofer.de/en.html' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
INSERT INTO document_search(document_id,search_text,updated_at) SELECT id,'fraunhofer technology trialed under real-world conditions - fraunhofer igd fraunhofer igd has developed a software solution that further automates the planning process for the roll-out of fiber-optic broadband. fibre3d enables deutsche telekom to submit applications to local government agencies without the need for costly and time-consuming site visits. this accelerates the approval process ensuring there are no delays to the expansion of germany s fiber-optic infrastructure. the software has now successfully completed a trial under real-world conditions. applied research',CURRENT_TIMESTAMP FROM documents WHERE canonical_hash='8783b6dc4af17bf234a5d240a4d4a1f6f7fca87017219bc7647d20c7ae220d6c' ON CONFLICT(document_id) DO UPDATE SET search_text=excluded.search_text,updated_at=CURRENT_TIMESTAMP;
INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-35844AC41B432D459FF5','applied_research',NULL,'Fraunhofer’s CorASiV project comes out with new software to assist health departments in tracking chains of infection - Fraunhofer IGD','https://www.igd.fraunhofer.de/en/media-center/news-from-the-institute/2020/fraunhofers-corasiv-project-comes-out-with-new-software-to-assist-health.html',NULL,'Computer Graphics Research',NULL,'Germany','Europe','official_research_institution',NULL,NULL,'2026-10-04T10:32:10.933Z','institutional_primary','en','© Fraunhofer IGD A visual preparation of the Covid-19 data supports health departments. Following the sudden rise of COVID-19 in recent weeks, doctors, government officials, and health departments are stressing the possibility of an uncontrollable spread of the virus and the consequences of a second lockdown. Those consequences are unforeseeable in terms of the impact to both the economy and public health. In anticipation, the federal government is repeating its desperate appeal from mid-April to focus on tracking the sources of infection and the spread of the virus. This is exactly where the Fraunhofer Institute for Computer Graphics Research IGD and the Fraunhofer Institute for Optronics, System Technologies and Image Exploitation IOSB come in with their solutions.','© Fraunhofer IGD A visual preparation of the Covid-19 data supports health departments. Following the sudden rise of COVID-19 in recent weeks, doctors, government officials, and health departments are stressing the possibility of an uncontrollable spread of the virus and the consequences of a second lockdown. Those consequences are unforeseeable in terms of the impact to both the economy and public health. In anticipation, the federal government is repeating its desperate appeal from mid-April to focus on tracking the sources of infection and the spread of the virus. This is exactly where the Fraunhofer Institute for Computer Graphics Research IGD and the Fraunhofer Institute for Optronics, System Technologies and Image Exploitation IOSB come in with their solutions.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://www.igd.fraunhofer.de/en/media-center/news-from-the-institute/2020/fraunhofers-corasiv-project-comes-out-with-new-software-to-assist-health.html',NULL,3,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','850ad24505fb28595530bb90585bb02bf0fa31f79722a4dd4c0f105c3a230705','35844ac41b432d459ff536db9a894719a2ec05545a8e1e8bfac49b765ec7e0a4',1,1,1,1 FROM sources WHERE root_url='https://www.igd.fraunhofer.de/en.html' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
