INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-F9393DCD3AE09C8BAED0','applied_research',NULL,'Ocean Technology Campus: Making progress at the fishing port - Fraunhofer IGD','https://www.igd.fraunhofer.de/en/media-center/news-from-the-institute/2020/ocean-technology-campus-making-progress-at-the-fishing-port.html',NULL,'Computer Graphics Research',NULL,'Germany','Europe','official_research_institution',NULL,NULL,'2026-10-04T10:32:10.900Z','institutional_primary','en','Things are happening at Rostock’s fishing port: Standard Aggregatebau Evers GmbH & Co. KG (SAB) in Bramow has constructed a new office building at the edge of the wharf and have just started work on a new, approx. 4,100 m² multipurpose building. What’s special about this new building is that SAB isn’t building it just for its own purposes, it’s also taking the first players of the Ocean Technology Campus (OTC) under its wing.','Things are happening at Rostock’s fishing port: Standard Aggregatebau Evers GmbH & Co. KG (SAB) in Bramow has constructed a new office building at the edge of the wharf and have just started work on a new, approx. 4,100 m² multipurpose building. What’s special about this new building is that SAB isn’t building it just for its own purposes, it’s also taking the first players of the Ocean Technology Campus (OTC) under its wing.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://www.igd.fraunhofer.de/en/media-center/news-from-the-institute/2020/ocean-technology-campus-making-progress-at-the-fishing-port.html',NULL,3,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','75925f64d6750a1dbc5f78efebd6e1d9dde09645c19ff0857f06d6550476e9a7','f9393dcd3ae09c8baed005b57f8cf54184c224a2bc295036e0c3e3590fbc222c',1,1,1,1 FROM sources WHERE root_url='https://www.igd.fraunhofer.de/en.html' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
