INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-8AF3C0054ED77F89D269','applied_research',NULL,'Official kick-off of major technology research project in Baltic Sea - Fraunhofer IGD','https://www.igd.fraunhofer.de/en/media-center/news-from-the-institute/2019/official-kick-off-of-major-technology-research-project-in-baltic-sea.html',NULL,'Computer Graphics Research',NULL,'Germany','Europe','official_research_institution',NULL,NULL,'2026-10-04T10:32:10.014Z','institutional_primary','en','© Fraunhofer IGD Image (M): The new offshore infrastructure of the Digital Ocean Lab (DOL) allows underwater technology to be developed and tested under real ocean conditions. Various underwater testing areas are planned that will cover the entire spectrum of underwater applications (Rostock) As part of the Digital Ocean Convention Rostock -- an international symposium on underwater technology -- August 9, 2019 marked the symbolic kick-off for the start of a one-of-a-kind, large-scale project in the Baltic Sea, the grand vision of the Hanseatic city of Rostock: The Ocean Technology Campus (OTC). This flagship project has been vigorously promoted over the last six years by Fraunhofer, the Hanseatic and university city of Rostock, the state government, as well as partners in industry, and is now entering the implementation phase.','© Fraunhofer IGD Image (M): The new offshore infrastructure of the Digital Ocean Lab (DOL) allows underwater technology to be developed and tested under real ocean conditions. Various underwater testing areas are planned that will cover the entire spectrum of underwater applications (Rostock) As part of the Digital Ocean Convention Rostock -- an international symposium on underwater technology -- August 9, 2019 marked the symbolic kick-off for the start of a one-of-a-kind, large-scale project in the Baltic Sea, the grand vision of the Hanseatic city of Rostock: The Ocean Technology Campus (OTC). This flagship project has been vigorously promoted over the last six years by Fraunhofer, the Hanseatic and university city of Rostock, the state government, as well as partners in industry, and is now entering the implementation phase.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://www.igd.fraunhofer.de/en/media-center/news-from-the-institute/2019/official-kick-off-of-major-technology-research-project-in-baltic-sea.html',NULL,5,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','a8ba904b30eae18d9f13c4c0cf07d32bfe650ca949ae54952778705bfbff3155','8af3c0054ed77f89d269060675bbe73624dea10d752d922cca655ad339264ff0',1,1,1,1 FROM sources WHERE root_url='https://www.igd.fraunhofer.de/en.html' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
