INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-B5D8BF892C06B43DDFB9','applied_research',NULL,'Acoustic Inline Quality Assurance for Laser Ablation - Fraunhofer IDMT','https://www.idmt.fraunhofer.de/en/research-topics/industrial-sound-analysis/acoustic-inline-quality-assurance-for-laser-ablation.html',NULL,'Digital Media Technology',NULL,'Germany','Europe','official_research_institution',NULL,NULL,'2026-10-04T10:33:56.056Z','institutional_primary','en','Laser ablation generates characteristic acoustic signals that provide insights into the machining status of the products following AI-based analysis. This means that quality-relevant information is available during the process itself, eliminating the need for later stage determination and evaluation. Consequently, material transitions, residual coatings and incipient over-removal can be detected early on, enabling transparent assessment of product quality and avoiding scrap.','Laser ablation generates characteristic acoustic signals that provide insights into the machining status of the products following AI-based analysis. This means that quality-relevant information is available during the process itself, eliminating the need for later stage determination and evaluation. Consequently, material transitions, residual coatings and incipient over-removal can be detected early on, enabling transparent assessment of product quality and avoiding scrap.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://www.idmt.fraunhofer.de/en/research-topics/industrial-sound-analysis/acoustic-inline-quality-assurance-for-laser-ablation.html',NULL,2,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','504829f77d31eb2231fe49e2abba8eb5e17c39df7335932873f95dc1fc10d93e','b5d8bf892c06b43ddfb9b2a6f5d4649f4289768545e997978ffa47d8e6b5eca7',1,1,1,1 FROM sources WHERE root_url='https://www.idmt.fraunhofer.de/en.html' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
