INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-2114B1D4EA3D574F9B0D','applied_research',NULL,'Article in Science Advances on AI-based generation of synthetic radiographs - Fraunhofer MEVIS','https://www.mevis.fraunhofer.de/en/press-and-scicom/institute-news/2020/article-in-science-advances-on-ai-based-generation-of-synthetic-radiographs.html',NULL,'Digital Medicine',NULL,'Germany','Europe','official_research_institution',NULL,NULL,'2026-10-04T10:33:57.145Z','institutional_primary','en','The December issue of Science Advances contains the article Breaking Medical Data Sharing Boundaries by Employing Synthesized Radiographs by Tianyu Han. Three of the co-authors – Dorit Merhof, Fabian Kiessling, and Volkmar Schulz – have been affiliated with Fraunhofer MEVIS since 2018 as part of a strategic cooperation with the Comprehensive Diagnostic Center Aachen (CDCA) at the University Hospital RWTH Aachen, Germany. Tianyu Han is a PhD student within Volkmar Schulz’s research group, who is the corresponding and shared last author of this study.','The December issue of Science Advances contains the article Breaking Medical Data Sharing Boundaries by Employing Synthesized Radiographs by Tianyu Han. Three of the co-authors – Dorit Merhof, Fabian Kiessling, and Volkmar Schulz – have been affiliated with Fraunhofer MEVIS since 2018 as part of a strategic cooperation with the Comprehensive Diagnostic Center Aachen (CDCA) at the University Hospital RWTH Aachen, Germany. Tianyu Han is a PhD student within Volkmar Schulz’s research group, who is the corresponding and shared last author of this study.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://www.mevis.fraunhofer.de/en/press-and-scicom/institute-news/2020/article-in-science-advances-on-ai-based-generation-of-synthetic-radiographs.html',NULL,3,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','a7c93a7c857a6f7af0723ba024cd945a21011f423fa2c429feb96f8b908fce9a','2114b1d4ea3d574f9b0d38a90820b21addbdceeb9bd4f2509dc9e1f999b4affc',1,1,1,1 FROM sources WHERE root_url='https://www.mevis.fraunhofer.de/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
