INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-0788B7DC61B36B0BD91A','applied_research',NULL,'Customized Therapy for Breast Cancer Patients - Researchers in the VPH-PRISM Project Develop New Procedures to Improve Treatment of Breast Cancer Using Multidisciplinary Image Data - Fraunhofer MEVIS','https://www.mevis.fraunhofer.de/en/press-and-scicom/press-release/customized-therapy-for-breast-cancer-patients.html',NULL,'Digital Medicine',NULL,'Germany','Europe','official_research_institution',NULL,NULL,'2026-10-04T10:33:57.272Z','institutional_primary','en','Every tenth woman is afflicted with breast cancer during her lifetime. The diagnosis and treatment of a patient involves the collaboration of a wide range of specialists. The broad range of software platforms for storage and visualization of medical imaging data used by radiologists, pathologists, oncologists, radiotherapists and surgeons, brings challenges for communication and data transfer between the platforms. Improved extraction and transfer of information between the platforms may support breast cancer diagnosis and therapy planning.','Every tenth woman is afflicted with breast cancer during her lifetime. The diagnosis and treatment of a patient involves the collaboration of a wide range of specialists. The broad range of software platforms for storage and visualization of medical imaging data used by radiologists, pathologists, oncologists, radiotherapists and surgeons, brings challenges for communication and data transfer between the platforms. Improved extraction and transfer of information between the platforms may support breast cancer diagnosis and therapy planning.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://www.mevis.fraunhofer.de/en/press-and-scicom/press-release/customized-therapy-for-breast-cancer-patients.html',NULL,3,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','b4e68f0d557fae6573e6a8423033b4dbefdb60711b0ce0b51ad9a1b83e496524','0788b7dc61b36b0bd91a6aa228e2d3fed3ddb1d328e8a8c72ef4290611f62458',1,1,1,1 FROM sources WHERE root_url='https://www.mevis.fraunhofer.de/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
