INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-14F6362E2679C7301A0D','applied_research',NULL,'3D Integration - Fraunhofer ENAS','https://www.enas.fraunhofer.de/en/Business_Units/Process,_Device_and_Packaging_Technology/3D_MEMS_Packaging/interconnects.html',NULL,'Electronic Nano Systems',NULL,'Germany','Europe','official_research_institution',NULL,NULL,'2026-10-04T10:34:54.025Z','institutional_primary','en','For the system integration, various concepts like System-on-Chip (SoC), System-in-Package (SiP) or System-on-Package (SoP), have been developed. Novel SiP concepts introduce the third dimension, which results in complex system architectures. The 3D integration by Through Silicon Vias (TSV) or Through Glas Vias (TGV) is one of the most promising approaches. However, 3D integration by TSV or TGV is challenging due to numerous and customized types of MEMS manufacturing processes, material combinations and packaging methods. In addition, requirements regarding the ambiance and its media have to be fulfilled, such as openings for pressure equalization for pressure sensors or a hermetic sealing for acceleration sensors. Therefore, the advanced 3D integration techniques known from microelectronics cannot easily be transferred to MEMS. Instead, different constraints demand different approaches f','For the system integration, various concepts like System-on-Chip (SoC), System-in-Package (SiP) or System-on-Package (SoP), have been developed. Novel SiP concepts introduce the third dimension, which results in complex system architectures. The 3D integration by Through Silicon Vias (TSV) or Through Glas Vias (TGV) is one of the most promising approaches. However, 3D integration by TSV or TGV is challenging due to numerous and customized types of MEMS manufacturing processes, material combinations and packaging methods. In addition, requirements regarding the ambiance and its media have to be fulfilled, such as openings for pressure equalization for pressure sensors or a hermetic sealing for acceleration sensors. Therefore, the advanced 3D integration techniques known from microelectronics cannot easily be transferred to MEMS. Instead, different constraints demand different approaches f',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://www.enas.fraunhofer.de/en/Business_Units/Process,_Device_and_Packaging_Technology/3D_MEMS_Packaging/interconnects.html',NULL,2,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','b6c33e0b6afc9b3b3008e74538cce4f41eade776f14b04829773de4f518db33c','14f6362e2679c7301a0d96c88bb29bc6f21efc9e6f3812c85a78afc965284323',1,1,1,1 FROM sources WHERE root_url='https://www.enas.fraunhofer.de/en.html' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
INSERT INTO document_search(document_id,search_text,updated_at) SELECT id,'3d integration - fraunhofer enas for the system integration various concepts like system-on-chip soc system-in-package sip or system-on-package sop have been developed. novel sip concepts introduce the third dimension which results in complex system architectures. the 3d integration by through silicon vias tsv or through glas vias tgv is one of the most promising approaches. however 3d integration by tsv or tgv is challenging due to numerous and customized types of mems manufacturing processes material combinations and packaging methods. in addition requirements regarding the ambiance and its media have to be fulfilled such as openings for pressure equalization for pressure sensors or a hermetic sealing for acceleration sensors. therefore the advanced 3d integration techniques known from microelectronics cannot easily be transferred to mems. instead different constraints demand different approaches f applied research',CURRENT_TIMESTAMP FROM documents WHERE canonical_hash='14f6362e2679c7301a0d96c88bb29bc6f21efc9e6f3812c85a78afc965284323' ON CONFLICT(document_id) DO UPDATE SET search_text=excluded.search_text,updated_at=CURRENT_TIMESTAMP;
INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-4E91D4241F3C8C95941D','applied_research',NULL,'3D/MEMS Packaging - Fraunhofer ENAS','https://www.enas.fraunhofer.de/en/Business_Units/Process,_Device_and_Packaging_Technology/3D_MEMS_Packaging.html',NULL,'Electronic Nano Systems',NULL,'Germany','Europe','official_research_institution',NULL,NULL,'2026-10-04T10:34:53.891Z','institutional_primary','en','Fraunhofer ENAS is a leading research institute for the integration and reliability assessment of micro- and nanoelectronic systems. In the field of “3D/MEMS Packaging”, packaging and interconnect technologies for MEMS/NEMS, power and sensor modules, and hybrid 3D integration solutions are developed and tested in chip-, wafer-, component-, and system-level packaging. The portfolio ranges from classical assembly and interconnection techniques through additive printing methods and comprehensive characterization and reliability analysis − with particular expertise for demanding applications in harsh environments, power electronics, chiplet architectures and biocompatible microsystems. The entire spectrum of “System Packaging” across all major integration levels of micro- and nanoelectronic systems is covered − from the chip and wafer level through the package to the system- or board-level.','Fraunhofer ENAS is a leading research institute for the integration and reliability assessment of micro- and nanoelectronic systems. In the field of “3D/MEMS Packaging”, packaging and interconnect technologies for MEMS/NEMS, power and sensor modules, and hybrid 3D integration solutions are developed and tested in chip-, wafer-, component-, and system-level packaging. The portfolio ranges from classical assembly and interconnection techniques through additive printing methods and comprehensive characterization and reliability analysis − with particular expertise for demanding applications in harsh environments, power electronics, chiplet architectures and biocompatible microsystems. The entire spectrum of “System Packaging” across all major integration levels of micro- and nanoelectronic systems is covered − from the chip and wafer level through the package to the system- or board-level.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://www.enas.fraunhofer.de/en/Business_Units/Process,_Device_and_Packaging_Technology/3D_MEMS_Packaging.html',NULL,2,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','10b7cd8c623af6186c7c914995067f3931fe86442b37f755f911b3ba2ccd3407','4e91d4241f3c8c95941d37bca73bd47fa19589496582bc63027fc67f09b67dcc',1,1,1,1 FROM sources WHERE root_url='https://www.enas.fraunhofer.de/en.html' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
INSERT INTO document_search(document_id,search_text,updated_at) SELECT id,'3d mems packaging - fraunhofer enas fraunhofer enas is a leading research institute for the integration and reliability assessment of micro- and nanoelectronic systems. in the field of 3d mems packaging packaging and interconnect technologies for mems nems power and sensor modules and hybrid 3d integration solutions are developed and tested in chip- wafer- component- and system-level packaging. the portfolio ranges from classical assembly and interconnection techniques through additive printing methods and comprehensive characterization and reliability analysis with particular expertise for demanding applications in harsh environments power electronics chiplet architectures and biocompatible microsystems. the entire spectrum of system packaging across all major integration levels of micro- and nanoelectronic systems is covered from the chip and wafer level through the package to the system- or board-level. applied research',CURRENT_TIMESTAMP FROM documents WHERE canonical_hash='4e91d4241f3c8c95941d37bca73bd47fa19589496582bc63027fc67f09b67dcc' ON CONFLICT(document_id) DO UPDATE SET search_text=excluded.search_text,updated_at=CURRENT_TIMESTAMP;
INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-23C8999450BC8D2DDDEE','applied_research',NULL,'Airgap insulated microstructures - Fraunhofer ENAS','https://www.enas.fraunhofer.de/en/Business_Units/Process,_Device_and_Packaging_Technology/MEMS_Technology_platforms/Airgap_insulated_microstructures.html',NULL,'Electronic Nano Systems',NULL,'Germany','Europe','official_research_institution',NULL,NULL,'2026-10-04T10:34:54.038Z','institutional_primary','en','This technology platform uses standard Si wafers and enables the structuring of moving elements from the surface into the Si crystal. The electrical and mechanical contacting of the active structures takes place via a large number of thin metallic fingers on special carrier-layer systems. The electrical insulation is organized in the lateral and vertical direction by air gaps. Existing patents are related to post-process gap reduction and fixation methods in order to increase the capacitive sensitivity.','This technology platform uses standard Si wafers and enables the structuring of moving elements from the surface into the Si crystal. The electrical and mechanical contacting of the active structures takes place via a large number of thin metallic fingers on special carrier-layer systems. The electrical insulation is organized in the lateral and vertical direction by air gaps. Existing patents are related to post-process gap reduction and fixation methods in order to increase the capacitive sensitivity.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://www.enas.fraunhofer.de/en/Business_Units/Process,_Device_and_Packaging_Technology/MEMS_Technology_platforms/Airgap_insulated_microstructures.html',NULL,2,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','658bd507f3a462b96b06fdf2de4fafaf52754aa6c66afc473d8701f4d5df857a','23c8999450bc8d2dddee6109be57144354a8aaff6cb71492396c374be519b407',1,1,1,1 FROM sources WHERE root_url='https://www.enas.fraunhofer.de/en.html' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
