INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-0CA43499A61BA10FF734','applied_research',NULL,'Bulk Micromachining - Fraunhofer ENAS','https://www.enas.fraunhofer.de/en/Business_Units/Process,_Device_and_Packaging_Technology/MEMS_Technology_platforms/Bulk_Micromachining.html',NULL,'Electronic Nano Systems',NULL,'Germany','Europe','official_research_institution',NULL,NULL,'2026-10-04T10:34:54.163Z','institutional_primary','en','This technology platform enables the three-dimensional structuring of silicon wafers using wet and dry etching processes in various combinations. The structuring steps for further layers are embedded in this process sequence, such as e.g. SiO 2 and Si 3 N 4 layers for electrical insulation, metallic layers for electrical contacting or dielectric layers for optically active areas.','This technology platform enables the three-dimensional structuring of silicon wafers using wet and dry etching processes in various combinations. The structuring steps for further layers are embedded in this process sequence, such as e.g. SiO 2 and Si 3 N 4 layers for electrical insulation, metallic layers for electrical contacting or dielectric layers for optically active areas.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://www.enas.fraunhofer.de/en/Business_Units/Process,_Device_and_Packaging_Technology/MEMS_Technology_platforms/Bulk_Micromachining.h