INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-ED90396495847B6D17FB','applied_research',NULL,'Process, Device and Packaging Technologies - Fraunhofer ENAS','https://www.enas.fraunhofer.de/en/Business_Units/Process,_Device_and_Packaging_Technology.html',NULL,'Electronic Nano Systems',NULL,'Germany','Europe','official_research_institution',NULL,NULL,'2026-10-04T10:34:53.881Z','institutional_primary','en','The business unit Process, Device and Packaging Technologies bundles all processes of clean room technologies (micro- and nanotechnologies) at Fraunhofer ENAS in close cooperation with the Center for Microtechnologies at the Chemnitz University of Technology. Thus, it comprises the individual processes and technologies as a basis for the development of electronic components, sensors and actuators, including their packaging (MEMS, wafer-level packaging and heterointegration of different components). This is complemented by the simulation of processes, equipment, materials and components of micro- and nanoelectronics.','The business unit Process, Device and Packaging Technologies bundles all processes of clean room technologies (micro- and nanotechnologies) at Fraunhofer ENAS in close cooperation with the Center for Microtechnologies at the Chemnitz University of Technology. Thus, it comprises the individual processes and technologies as a basis for the development of electronic components, sensors and actuators, including their packaging (MEMS, wafer-level packaging and heterointegration of different components). This is complemented by the simulation of processes, equipment, materials and components of micro- and nanoelectronics.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://www.enas.fraunhofer.de/en/Business_Units/Process,_Device_and_Packaging_Technology.html',NULL,2,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','ec0ca3b0b2d53682687e1096ad1afee988d634845666682958880bb0f0230b63','ed90396495847b6d17fb8f4043c5c1eb658fa1b2e59ff86bb91136f6001346f3',1,1,1,1 FROM sources WHERE root_url='https://www.enas.fraunhofer.de/en.html' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
