INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-9F897CF440C9248773F1','applied_research',NULL,'Wafer-to-Wafer-Bonding - Fraunhofer ENAS','https://www.enas.fraunhofer.de/en/Business_Units/Process,_Device_and_Packaging_Technology/3D_MEMS_Packaging/Wafer_to_Wafer_bonding.html',NULL,'Electronic Nano Systems',NULL,'Germany','Europe','official_research_institution',NULL,NULL,'2026-10-04T10:34:54.017Z','institutional_primary','en','Wafer bonding is a process for temporary or permanent joining of two or more wafers with or without an intermediate layer. Wafer bonding has various applications: packaging (e.g. for sensors and actuators), assembly (e.g. for RF components), integration (e.g. for electrical/micromechanical/optical component), substrate and device fabrication.The System Packaging department offers standard wafer level bonding technologies such as silicon direct, anodic, glass frit and adhesive bonding. These technologies can be adapted according to the specific requirements of target applications.','Wafer bonding is a process for temporary or permanent joining of two or more wafers with or without an intermediate layer. Wafer bonding has various applications: packaging (e.g. for sensors and actuators), assembly (e.g. for RF components), integration (e.g. for electrical/micromechanical/optical component), substrate and device fabrication.The System Packaging department offers standard wafer level bonding technologies such as silicon direct, anodic, glass frit and adhesive bonding. These technologies can be adapted according to the specific requirements of target applications.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://www.enas.fraunhofer.de/en/Business_Units/Process,_Device_and_Packaging_Technology/3D_MEMS_Packaging/Wafer_to_Wafer_bonding.html',NULL,2,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','6a54f6f7a9efed0c4adb66a21be9a4ba7fd68e7a458cc92f48bfb14604d41998','9f897cf440c9248773f194693dd79f02da974a54543828f4c3f1b08da1a286a6',1,1,1,1 FROM sources WHERE root_url='https://www.enas.fraunhofer.de/en.html' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
