INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-1ED6C817F40F5036A1B7','applied_research',NULL,'Energy planning reimagined: OASES provides open data and models for Africa and Europe','https://www.iee.fraunhofer.de/en/presse-infothek/press-media/2025/energyplanning-reimagined-OASES-provides-open-data-and-models-for-africa-and-europe.html',NULL,'Energy Economics and Energy System Technology',NULL,'Germany','Europe','official_research_institution','2025-09-08T11:01:00Z',NULL,'2026-10-04T10:35:28.425Z','institutional_primary','en','The expansion of renewable energies (RE) is progressing worldwide, but in many places there is a lack of reliable data and suitable modelling tools. This shortage also hinders the utilization of enormous RE potential in African countries. As part of the OASES research project, the Fraunhofer Institute for Energy Economics and Energy System Technology IEE and its partners have therefore established an open AU-EU ecosystem for energy system modelling. Alongside a tool for the automated detection of RE plants in satellite imagery, high-resolution RE time series were generated and can be seamlessly integrated into the enhanced and user-friendly IRENA FlexTool.','The expansion of renewable energies (RE) is progressing worldwide, but in many places there is a lack of reliable data and suitable modelling tools. This shortage also hinders the utilization of enormous RE potential in African countries. As part of the OASES research project, the Fraunhofer Institute for Energy Economics and Energy System Technology IEE and its partners have therefore established an open AU-EU ecosystem for energy system modelling. Alongside a tool for the automated detection of RE plants in satellite imagery, high-resolution RE time series were generated and can be seamlessly integrated into the enhanced and user-friendly IRENA FlexTool.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://www.iee.fraunhofer.de/en/presse-infothek/press-media/2025/energyplanning-reimagined-OASES-provides-open-data-and-models-for-africa-and-europe.html',NULL,3,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','1f94e32608865ec14dd7a3e3d681869d76de7b0367122a1a54f4a5e007cdc9d3','1ed6c817f40f5036a1b7377e30c2743fb549de8591312cfcdddf15314af5b4c1',1,1,1,1 FROM sources WHERE root_url='https://www.iee.fraunhofer.de/en.html' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
