INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-C03F15E6579A9A36ED17','applied_research',NULL,'New Whitepaper on influence on PtX certification on the ramp-up of a hydrogen export market in the SADC region','https://www.iee.fraunhofer.de/en/presse-infothek/press-media/2026/new-whitepaper-on-influence-on-ptx-certification-on-the-ramp-up-.html',NULL,'Energy Economics and Energy System Technology',NULL,'Germany','Europe','official_research_institution','2026-04-29T09:21:00Z',NULL,'2026-10-04T10:35:28.567Z','institutional_primary','en','How can countries in southern Africa become key players in the global trade in green hydrogen? And what role do sustainability and certification requirements in importing countries play in this process? A new whitepaper published by the Fraunhofer Institutes IEE, ISI, IEG and IMWS provides a first systematic analysis of how differing power‑to‑x (PtX) certification requirements influence the ramp‑up of hydrogen and synthetic fuel export markets from the SADC region – and why strategic decisions already in early project phases are crucial.','How can countries in southern Africa become key players in the global trade in green hydrogen? And what role do sustainability and certification requirements in importing countries play in this process? A new whitepaper published by the Fraunhofer Institutes IEE, ISI, IEG and IMWS provides a first systematic analysis of how differing p