INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-193FBE8E1EFF8CD8DA5C','applied_research',NULL,'Near-Surface Geothermal Energy - Fraunhofer IEG','https://www.ieg.fraunhofer.de/en/research-topics/georesources-and-geothermal-energy/near-surface-geothermal-energy.html',NULL,'Energy Infrastructures and Geotechnologies',NULL,'Germany','Europe','official_research_institution',NULL,NULL,'2026-10-04T10:35:28.750Z','institutional_primary','en','Our Near-Surface Geothermal Competence Centre offers services in the field of innovative, near-surface geothermal supply systems. In addition to classic development and utilisation concepts, this also includes probes up to 1000 m deep. Our portfolio for concept development and validation includes both grid-based and object-based projects. We plan and design the integration of heat pump systems for heating and cooling purposes, their monitoring and optimisation, the integration of other renewable energies / sector coupling (PV, PV-T, solar, waste heat) as well as the associated load management and the measurement technology and monitoring strategies required for this. We accompany projects with numerical analytics and multi-criteria analyses and support our partners with innovation consulting, training and product development. In addition, we strive for active further development and opti','Our Near-Surface Geothermal Competence Centre offers services in the field of innovative, near-surface geothermal supply systems. In addition to classic development and utilisation concepts, this also includes probes up to 1000 m deep. Our portfolio for concept development and validation includes both grid-based and object-based projects. We plan and design the integration of heat pump systems for heating and cooling purposes, their monitoring and optimisation, the integration of other renewable energies / sector coupling (PV, PV-T, solar, waste heat) as well as the associated load management and the measurement technology and monitoring strategies required for this. We accompany projects with numerical analytics and multi-criteria analyses and support our partners with innovation consulting, training and product development. In addition, we strive for active further development and opti',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://www.ieg.fraunhofer.de/en/research-topics/georesources-and-geothermal-energy/near-surface-geothermal-energy.html',NULL,3,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','5bee9064d5676fef4f1b69ad8893b50ad011df94587000600deda0c65e5b55b6','193fbe8e1eff8cd8da5ce308ee816832806e26d8cd6f2244dfbe2fa4573f8c84',1,1,1,1 FROM sources WHERE root_url='https://www.ieg.fraunhofer.de/en.html' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
