INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-0B2DDE16A661C392595D','applied_research',NULL,'Thermal Networks and Systems - Fraunhofer IEG','https://www.ieg.fraunhofer.de/en/research-topics/networks-energy-process-engineering/thermal-networks-and-systems.html',NULL,'Energy Infrastructures and Geotechnologies',NULL,'Germany','Europe','official_research_institution',NULL,NULL,'2026-10-04T10:35:28.890Z','institutional_primary','en','The Competence Center for Thermal Networks and Systems works on current issues associated with grid-based heating and cooling supply. We support our customers from the district heating sector in the development and implementation of strategies for the transformation and decarbonization of their existing heating networks and develop concepts and solutions for efficient and sustainable supply systems based on "cold" district and local heating and bidirectional networks for new construction. Our main focus is on the integration and combination of renewable heat and cold sources as well as short- and long-term storage and on the integration of thermodynamic converters. Both in the area of existing networks and in the area of new construction, we support our customers by means of comprehensive screening to identify suitable funding opportunities for their projects.','The Competence Center for Thermal Networks and Systems works on current issues associated with grid-based heating and cooling supply. We support our customers from the district heating sector in the development and implementation of strategies for the transformation and decarbonization of their existing heating networks and develop concepts and solutions for efficient and sustainable supply systems based on "cold" district and local heating and bidirectional networks for new construction. Our main focus is on the integration and combination of renewable heat and cold sources as well as short- and long-term storage and on the integration of thermodynamic converters. Both in the area of existing networks and in the area of new construction, we support our customers by means of comprehensive screening to identify suitable funding opportunities for their projects.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://www.ieg.fraunhofer.de/en/research-topics/networks-energy-process-engineering/thermal-networks-and-systems.html',NULL,3,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','80ffe047268f814a4f67f32b0c653e443b3a0325916f608510fdedfccf9956b2','0b2dde16a661c392595db893f4c25dc6adfacd367b999cd46bfadd9b8564f6fe',1,1,1,1 FROM sources WHERE root_url='https://www.ieg.fraunhofer.de/en.html' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
