INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-E6BD76C746C08D117341','earth_science',NULL,'Notice of Study for an Environmental Assessment of the Proposed Construction of a Laboratory and Office Facility to Support U.S. Geological Survey and Colorado School of Mines Energy and Mineral Science Operations | U.S. Geological Survey','https://www.usgs.gov/media/files/notice-study-environmental-assessment-proposed-construction-laboratory-and-office',NULL,'3-D CT Core Imaging Laboratory',NULL,'United States','North America','official_research_institution','2022-08-15T12:00:00Z',NULL,'2026-10-04T10:27:27.430Z','institutional_primary','en','In accordance with the National Environmental Policy Act of 1969, as amended, the U.S. Geological Survey (USGS) has issued a Notice of Study for an Environmental Assessment (EA) of a proposed laboratory and office facility to support USGS and Colorado School of Mines Energy and Mineral Science Operations. This Notice of Study initiates a period of study for the EA not to exceed one year.','In accordance with the National Environmental Policy Act of 1969, as amended, the U.S. Geological Survey (USGS) has issued a Notice of Study for an Environmental Assessment (EA) of a proposed laboratory and office facility to support USGS and Colorado School of Mines Energy and Mineral Science Operations. This Notice of Study initiates a period of study for the EA not to exceed one year.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://www.usgs.gov/media/files/notice-study-environmental-assessment-proposed-construction-laboratory-and-office',NULL,3,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','3d23b791237315ae7af91a277b8ac21d7c173fdd8f910df89643b9d8ba053ad2','e6bd76c746c08d117341ad5b36d760c7e0b6b2f89fc7fb66b27c0eb31c6eb13e',1,1,1,1 FROM sources WHERE root_url='https://www.usgs.gov/labs/santa-cruz-core-scanning-laboratory' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
