INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-2B0F7CDFDD82FC959D70','earth_science',NULL,'Petroleum Geochemistry Research Laboratory Programmed Pyrolysis Method | U.S. Geological Survey','https://www.usgs.gov/media/files/petroleum-geochemistry-research-laboratory-programmed-pyrolysis-method',NULL,'3-D CT Core Imaging Laboratory',NULL,'United States','North America','official_research_institution','2021-09-28T06:00:00Z',NULL,'2026-10-04T10:27:19.348Z','institutional_primary','en','Programmed pyrolysis is a rapid analytical technique used as a screening tool to evaluate source rock hydrocarbon-generating potential and thermal maturity. The Petroleum Geochemistry Research Laboratory (PGRL) method is a modification of the original and most widely used temperature program for this kind of analysis (Barker, 1974; Espitalie and others, 1977; Peters, 1986; Espitalie and Bordenave, 1993; Peters and Rodriguez, 2017).','Programmed pyrolysis is a rapid analytical technique used as a screening tool to evaluate source rock hydrocarbon-generating potential and thermal maturity. The Petroleum Geochemistry Research Laboratory (PGRL) method is a modification of the original and most widely used temperature program for this kind of analysis (Barker, 1974; Espitalie and others, 1977; Peters, 1986; Espitalie and Bordenave, 1993; Peters and Rodriguez, 2017).',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://www.usgs.gov/media/files/petroleum-geochemistry-research-laboratory-programmed-pyrolysis-method',NULL,4,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','01de44a55d7c872c35eefeaf90c8fa4bf9cb8a1d310aead8e492764c6214ab77','2b0f7cdfdd82fc959d7083568b13fd0139840c05cfbd556c4878803b54da7909',1,1,1,1 FROM sources WHERE root_url='https://www.usgs.gov/labs/santa-cruz-core-scanning-laboratory' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
