INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-571174E96E006AC70DCC','earth_science',NULL,'TM00-01S Analysis and interpretation of reporting environmental data with a non-proper calibration curve for Kjeldahl nitrogen and phosphorus methods; Supplementary Infromation | U.S. Geological Survey','https://www.usgs.gov/media/files/tm00-01s-analysis-and-interpretation-reporting-environmental-data-a-non-proper',NULL,'3-D CT Core Imaging Laboratory',NULL,'United States','North America','official_research_institution','2000-01-07T14:45:30Z',NULL,'2026-10-04T10:27:33.487Z','institutional_primary','en','For the time period between April 20, and October 4, 1999, samples were analyzed by a modified calibration model. An additional low concentration standard was added that improperly eliminated the blank standard from the calibration model. It was initially thought that the blank was critical in the calibration model, by introducing potentially a 0.01 and 0.05 mg/L high bias in results for phosphorus and nitrogen, respectively. Additional data analysis described here, shows that the nonstandard calibration model was still a good model to determine the phosphorus and nitrogen concentrations in environmental samples. The correct 8-point calibration model with the blank standard was developed and all original sample data were processed through the calculation, giving paired results. The variances observed in the data set would be caused entirely by the original nonstandard calibration model a','For the time period between April 20, and October 4, 1999, samples were analyzed by a modified calibration model. An additional low concentration standard was added that improperly eliminated the blank standard from the calibration model. It was initially thought that the blank was critical in the calibration model, by introducing potentially a 0.01 and 0.05 mg/L high bias in results for phosphorus and nitrogen, respectively. Additional data analysis described here, shows that the nonstandard calibration model was still a good model to determine the phosphorus and nitrogen concentrations in environmental samples. The correct 8-point calibration model with the blank standard was developed and all original sample data were processed through the calculation, giving paired results. The variances observed in the data set would be caused entirely by the original nonstandard calibration model a',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://www.usgs.gov/media/files/tm00-01s-analysis-and-interpretation-reporting-environmental-data-a-non-proper',NULL,3,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','8b707d94e61b98ee917ed0cd97f5418a5003f57540c32f92c5fd30de1efd37ba','571174e96e006ac70dcc20aeb05642fd96f800cdae45a31bfb49852d2b9934e4',1,1,1,1 FROM sources WHERE root_url='https://www.usgs.gov/labs/santa-cruz-core-scanning-laboratory' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
INSERT INTO document_search(document_id,search_text,updated_at) SELECT id,'tm00-01s analysis and interpretation of reporting environmental data with a non-proper calibration curve for kjeldahl nitrogen and phosphorus methods supplementary infromation u.s. geological survey for the time period between april 20 and october 4 1999 samples were analyzed by a modified calibration model. an additional low concentration standard was added that improperly eliminated the blank standard from the calibration model. it was initially thought that the blank was critical in the calibration model by introducing potentially a 0.01 and 0.05 mg l high bias in results for phosphorus and nitrogen respectively. additional data analysis described here shows that the nonstandard calibration model was still a good model to determine the phosphorus and nitrogen concentrations in environmental samples. the correct 8-point calibration model with the blank standard was developed and all original sample data were processed through the calculation giving paired results. the variances observed in the data set would be caused entirely by the original nonstandard calibration model a earth science',CURRENT_TIMESTAMP FROM documents WHERE canonical_hash='571174e96e006ac70dcc20aeb05642fd96f800cdae45a31bfb49852d2b9934e4' ON CONFLICT(document_id) DO UPDATE SET search_text=excluded.search_text,updated_at=CURRENT_TIMESTAMP;
INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-2B529AC80CB8AC75A077','earth_science',NULL,'TM03-01 Data-reporting conventions and implications for interpreting results from custom method 9060 for samples collected from March 1, 1999, to December 31, 1999 | U.S. Geological Survey','https://www.usgs.gov/media/files/tm03-01-data-reporting-conventions-and-implications-interpreting-results-custom-method',NULL,'3-D CT Core Imaging Laboratory',NULL,'United States','North America','official_research_institution','2003-02-28T13:19:39Z',NULL,'2026-10-04T10:27:33.373Z','institutional_primary','en','Most samples analyzed using custom laboratory code 9060 (LC9060) between March 1999 and March 18, 2000 were subject to extended holding times. This technical memorandum describes the holding time studies undertaken at the NWQL to evaluate the effects of these extended holding times and guidance for the interpretation of these results. Data recoding procedures that the NWQL will implement also are described. This recoding is undertaken so that these results are properly remarked and qualified for USGS and public use. These results are part of a multiyear LC9060 data set, and this technical memorandum provides the time history of changes to LC9060 up until the approval of the official method SH2060. Also described are the recoding procedures that the NWQL will apply to ensure (1) consistency within the LC9060 dataset and (2) compatibility with SH2060 results. The recoding to produce this c','Most samples analyzed using custom laboratory code 9060 (LC9060) between March 1999 and March 18, 2000 were subject to extended holding times. This technical memorandum describes the holding time studies undertaken at the NWQL to evaluate the effects of these extended holding times and guidance for the interpretation of these results. Data recoding procedures that the NWQL will implement also are described. This recoding is undertaken so that these results are properly remarked and qualified for USGS and public use. These results are part of a multiyear LC9060 data set, and this technical memorandum provides the time history of changes to LC9060 up until the approval of the official method SH2060. Also described are the recoding procedures that the NWQL will apply to ensure (1) consistency within the LC9060 dataset and (2) compatibility with SH2060 results. The recoding to produce this c',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://www.usgs.gov/media/files/tm03-01-data-reporting-conventions-and-implications-interpreting-results-custom-method',NULL,3,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','eed9c50199e3a4991f20e07bf585da9cbcc0f630366ea7c0f19c3ae3a93aa82c','2b529ac80cb8ac75a0774f178c40b0dc20997c8583df6ba50c773f856afd237a',1,1,1,1 FROM sources WHERE root_url='https://www.usgs.gov/labs/santa-cruz-core-scanning-laboratory' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
INSERT INTO document_search(document_id,search_text,updated_at) SELECT id,'tm03-01 data-reporting conventions and implications for interpreting results from custom method 9060 for samples collected from march 1 1999 to december 31 1999 u.s. geological survey most samples analyzed using custom laboratory code 9060 lc9060 between march 1999 and march 18 2000 were subject to extended holding times. this technical memorandum describes the holding time studies undertaken at the nwql to evaluate the effects of these extended holding times and guidance for the interpretation of these results. data recoding procedures that the nwql will implement also are described. this recoding is undertaken so that these results are properly remarked and qualified for usgs and public use. these results are part of a multiyear lc9060 data set and this technical memorandum provides the time history of changes to lc9060 up until the approval of the official method sh2060. also described are the recoding procedures that the nwql will apply to ensure 1 consistency within the lc9060 dataset and 2 compatibility with sh2060 results. the recoding to produce this c earth science',CURRENT_TIMESTAMP FROM documents WHERE canonical_hash='2b529ac80cb8ac75a0774f178c40b0dc20997c8583df6ba50c773f856afd237a' ON CONFLICT(document_id) DO UPDATE SET search_text=excluded.search_text,updated_at=CURRENT_TIMESTAMP;
