INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-63CF31A6974DA83F9F66','public_higher_education_research',NULL,'AFIT / Applied Research Center for Hypersonics','https://www.afit.edu/ARCH/',NULL,'Air Force Institute of Technology-Graduate School of Engineering & Management',NULL,'United States','North America','public_graduate_higher_education_research_source',NULL,NULL,'2026-10-04T10:28:48.330Z','institutional_primary','en','Our Center addresses defense-focused challenges in hypersonics by delivering interdisciplinary expert solutions through educational excellence, relevant workforce development, and subject matter expertise. We conduct in-depth research in aerothermodynamics, propulsion, materials & structures, hypersonic vehicle performance, systems/digital engineering, and hypersonic vehicle design. Our faculty, staff, and student members cultivate and maintain strong collaborative connections with industry, academia, and government organization across the aerospace industry, securing and maintaining U.S. hypersonics science and technology. We provide introductory and advanced education and training within the Department of Aeronautics & Astronautics, in-person short-courses, and on-site delivery of workshops in hypersonics.','Our Center addresses defense-focused challenges in hypersonics by delivering interdisciplinary expert solutions through educational excellence, relevant workforce development, and subject matter expertise. We conduct in-depth research in aerothermodynamics, propulsion, materials & structures, hypersonic vehicle performance, systems/digital engineering, and hypersonic vehicle design. Our faculty, staff, and student members cultivate and maintain strong collaborative connections with industry, academia, and government organization across the aerospace industry, securing and maintaining U.S. hypersonics science and technology. We provide introductory and advanced education and training within the Department of Aeronautics & Astronautics, in-person short-courses, and on-site delivery of workshops in hypersonics.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://www.afit.edu/ARCH/',NULL,1,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','1198fa4dd00461a6b1434f762a24a91aa96f8e7a9602aacb6e9f3eb63e8e55e0','63cf31a6974da83f9f66d956585f0d94d3bf4d483632f2286f15eb090b1e4fb6',1,1,1,1 FROM sources WHERE root_url='https://www.afit.edu/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
