INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-2E20CAECACBE82D25661','public_higher_education_research',NULL,'AFIT / Artificial Intelligence Technology Research and Education Consortium (AI TREC)','https://www.afit.edu/AITREC/',NULL,'Air Force Institute of Technology-Graduate School of Engineering & Management',NULL,'United States','North America','public_graduate_higher_education_research_source',NULL,NULL,'2026-10-04T10:28:47.915Z','institutional_primary','en','Here, you''ll find detailed information on a variety of AI education programs available to students, insights into the innovative research projects driving AI advancements, and an overview of our key partnerships with leading organizations in the AI field. Whether you''re interested in pursuing advanced studies or staying informed about breakthroughs in AI, this page will guide you through AFIT''s role in shaping the future of AI technology and its application.','Here, you''ll find detailed information on a variety of AI education programs available to students, insights into the innovative research projects driving AI advancements, and an overview of our key partnerships with leading organizations in the AI field. Whether you''re interested in pursuing advanced studies or staying informed about breakthroughs in AI, this page will guide you through AFIT''s role in shaping the future of AI technology and its application.',NULL,NULL,NULL,NUL