INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-9C6B84E5911785B0E020','earth_science',NULL,'Navigating PFAS Contamination: Insights from the USGS Potomac River Watershed Study | U.S. Geological Survey','https://www.usgs.gov/programs/environmental-health-program/science/navigating-pfas-contamination-insights-usgs-potomac',NULL,'Arizona Water Science Center',NULL,'United States','North America','official_research_institution','2024-09-20T19:51:00Z',NULL,'2026-10-04T10:32:23.657Z','institutional_primary','en','The Potomac River is a major watershed in the eastern United States that serves as a crucial water supply for millions of people. USGS researchers conducted a comprehensive investigation to identify the contributions of municipal and industrial wastewater treatment plant effluent to the levels of per-and polyfluoroalkyl substances (PFAS) in the Potomac River. This study included measuring PFAS levels through sampling, analyzing their potential sources, creating models to understand how water flows and how people and wildlife may be exposed, and assessing health risks to both humans and the environment.','The Potomac River is a major watershed in the eastern United States that serves as a crucial water supply for millions of people. USGS researchers conducted a comprehensive investigation to identify the contributions of municipal and industrial wastewater treatment plant effluent to the levels of per-and polyfluoroalkyl substances (PFAS) in the Potomac River. This study included measuring PFAS levels through sampling, analyzing their potential sources, creating models to understand how water flows and how people and wildlife may be exposed, and assessing health risks to both humans and the environment.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://www.usgs.gov/programs/environmental-health-program/science/navigating-pfas-contamination-insights-usgs-potomac',NULL,5,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','34a551aadb47c15fc711429d56e70495ab1b83e2a568588832783191da5dd611','9c6b84e5911785b0e020c53a96785e14709663287adbd07b3ce50f837e97433b',1,1,1,1 FROM sources WHERE root_url='https://www.usgs.gov/centers/arizona-water-science-center' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
INSERT INTO document_search(document_id,search_text,updated_at) SELECT id,'navigating pfas contamination insights from the usgs potomac river watershed study u.s. geological survey the potomac river is a major watershed in the eastern united states that serves as a crucial water supply for millions of people. usgs researchers conducted a comprehensive investigation to identify the contributions of municipal and industrial wastewater treatment plant effluent to the levels of per-and polyfluoroalkyl substances pfas in the potomac river. this study included measuring pfas levels through sampling analyzing their potential sources creating models to understand how water flows and how people and wildlife may be exposed and assessing health risks to both humans and the environment. earth science',CURRENT_TIMESTAMP FROM documents WHERE canonical_hash='9c6b84e5911785b0e020c53a96785e14709663287adbd07b3ce50f837e97433b' ON CONFLICT(document_id) DO UPDATE SET search_text=excluded.search_text,updated_at=CURRENT_TIMESTAMP;
