INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-6C11AADA6961277EB691','earth_science',NULL,'Terrestrial Analogs for Research and Geologic Exploration Training (TARGET)​ | U.S. Geological Survey','https://www.usgs.gov/centers/astrogeology-science-center/science/terrestrial-analogs-research-and-geologic-exploration',NULL,'Astrogeology Science Center',NULL,'United States','North America','official_research_institution',NULL,NULL,'2026-10-04T10:33:34.951Z','institutional_primary','en','The U. S. Geological Survey (USGS) Astrogeology Science Center (ASC) recently established the Terrestrial Analogs for Research and Geologic Exploration Training (TARGET) program. This service-oriented program is built around the recognition that the Earth is a fundamental training ground for human and robotic planetary exploration, and that ASC is in a unique position in northern Arizona with access to a range of geologic analogs for planetary science and technology research. The ASC has a long history of responding to community needs and is currently working to provide the community with datasets, sample collections, logistical support, field guides, and other resources that support terrestrial analog fieldwork, testing, and data dissemination. Our vision is to lead the planetary science community in training, research, data archiving, and sample curation involving terrestrial analog fi','The U. S. Geological Survey (USGS) Astrogeology Science Center (ASC) recently established the Terrestrial Analogs for Research and Geologic Exploration Training (TARGET) program. This service-oriented program is built around the recognition that the Earth is a fundamental training ground for human and robotic planetary exploration, and that ASC is in a unique position in northern Arizona with access to a range of geologic analogs for planetary science and technology research. The ASC has a long history of responding to community needs and is currently working to provide the community with datasets, sample collections, logistical support, field guides, and other resources that support terrestrial analog fieldwork, testing, and data dissemination. Our vision is to lead the planetary science community in training, research, data archiving, and sample curation involving terrestrial analog fi',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://www.usgs.gov/centers/astrogeology-science-center/science/terrestrial-analogs-research-and-geologic-exploration',NULL,3,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','49519aa5914ebd6a707be76fdca3a0db1f209ff34192db2878176f561420a614','6c11aada6961277eb691fcb10a24647d269469d6a4c92976b7f123b0f78a3955',1,1,1,1 FROM sources WHERE root_url='https://www.usgs.gov/centers/astrogeology-science-center' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
INSERT INTO document_search(document_id,search_text,updated_at) SELECT id,'terrestrial analogs for research and geologic exploration training target u.s. geological survey the u. s. geological survey usgs astrogeology science center asc recently established the terrestrial analogs for research and geologic exploration training target program. this service-oriented program is built around the recognition that the earth is a fundamental training ground for human and robotic planetary exploration and that asc is in a unique position in northern arizona with access to a range of geologic analogs for planetary science and technology research. the asc has a long history of responding to community needs and is currently working to provide the community with datasets sample collections logistical support field guides and other resources that support terrestrial analog fieldwork testing and data dissemination. our vision is to lead the planetary science community in training research data archiving and sample curation involving terrestrial analog fi earth science',CURRENT_TIMESTAMP FROM documents WHERE canonical_hash='6c11aada6961277eb691fcb10a24647d269469d6a4c92976b7f123b0f78a3955' ON CONFLICT(document_id) DO UPDATE SET search_text=excluded.search_text,updated_at=CURRENT_TIMESTAMP;
