INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-E9818394046130B77F75','research',NULL,'Fundo de Amparo ao Trabalhador - FAT — Ministério da Ciência, Tecnologia e Inovação','https://www.gov.br/mcti/pt-br/acesso-a-informacao/acoes-e-programas/fundo-de-amparo-ao-trabalhador-fat',NULL,'AEB - Agência Espacial Brasileira',NULL,'Brazil','South America','government_science_network_unit',NULL,NULL,'2026-10-04T10:26:41.655Z','institutional_primary','pt','O Ministério da Ciência, Tecnologia e Inovações não desenvolve, em suas unidades orçamentárias, programas, ações, projetos e atividades financiados pelo Fundo de Amparo ao Trabalhador (FAT) Constituem Unidades Orçamentárias: a Administração Direta do MCTI (Sede e Unidades de Pesquisa) e suas Unidades Vinculadas: Conselho Nacional de Desenvolvimento Científico e Tecnológico - CNPq, Comissão Nacional de Energia Nuclear - CNEN, Agência Espacial Brasileira - AEB, Centro Nacional de Tecnologia Eletrônica Avançada - CEITEC e Fundo Nacional de Desenvolvimento Científico e Tecnológico - FNDCT, da Financiadora de Estudos e Projetos - FINEP.','O Ministério da Ciência, Tecnologia e Inovações não desenvolve, em suas unidades orçamentárias, programas, ações, projetos e atividades financiados pelo Fundo de Amparo ao Trabalhador (FAT) Constituem Unidades Orçamentárias: a Administração Direta do MCTI (Sede e Unidades de Pesquisa) e suas Unidades Vinculadas: Conselho Nacional de Desenvolvimento Científico e Tecnológico - CNPq, Comissão Nacional de Energia Nuclear - CNEN, Agência Espacial Brasileira - AEB, Centro Nacional de Tecnologia Eletrônica Avançada - CEITEC e Fundo Nacional de Desenvolvimento Científico e Tecnológico - FNDCT, da Financiadora de Estudos e Projetos - FINEP.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://www.gov.br/mcti/pt-br/acesso-a-informacao/acoes-e-programas/fundo-de-amparo-ao-trabalhador-fat',NULL,1,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','1d086b8b698d29a2582a3a77224be3c910cc86e25198306dadf3a0f7e52010d5','e9818394046130b77f75a595c7bfaba2abcd6991fb469177f2eadbf0f98e1407',1,1,1,1 FROM sources WHERE root_url='https://www.gov.br/mcti/pt-br/composicao/rede-mcti/agencia-espacial-brasileira' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
INSERT INTO document_search(document_id,search_text,updated_at) SELECT id,'fundo de amparo ao trabalhador - fat ministerio da ciencia tecnologia e inovacao o ministerio da ciencia tecnologia e inovacoes nao desenvolve em suas unidades orcamentarias programas acoes projetos e atividades financiados pelo fundo de amparo ao trabalhador fat constituem unidades orcamentarias a administracao direta do mcti sede e unidades de pesquisa e suas unidades vinculadas conselho nacional de desenvolvimento cientifico e tecnologico - cnpq comissao nacional de energia nuclear - cnen agencia espacial brasileira - aeb centro nacional de tecnologia eletronica avancada - ceitec e fundo nacional de desenvolvimento cientifico e tecnologico - fndct da financiadora de estudos e projetos - finep. research',CURRENT_TIMESTAMP FROM documents WHERE canonical_hash='e9818394046130b77f75a595c7bfaba2abcd6991fb469177f2eadbf0f98e1407' ON CONFLICT(document_id) DO UPDATE SET search_text=excluded.search_text,updated_at=CURRENT_TIMESTAMP;
INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-CF41437D5D0094FAC5DD','research',NULL,'Gestão Documental e Processo Eletrônico — Ministério da Ciência, Tecnologia e Inovação','https://www.gov.br/mcti/pt-br/acesso-a-informacao/processo-eletronico',NULL,'AEB - Agência Espacial Brasileira',NULL,'Brazil','South America','government_science_network_unit',NULL,NULL,'2026-10-04T10:26:42.454Z','institutional_primary','pt','Desde 2016, o Ministério da Ciência, Tecnologia e Inovação tornou eletrônicos todos os processos em tramitação no órgão, trabalhando-os de forma mais integrada e ágil a partir de uma plataforma virtual. O que motivou a iniciativa foi, dentre outros ganhos, a possibilidade de diminuir ao mínimo possível o estoque de papel (contribuindo para economia de recursos públicos e preservação do meio ambiente) e dar mais agilidade às análises.Estas diretrizes compõem o Decreto nº 8.539, de 08 de outubro de 2015 , que dispõe sobre o uso do meio eletrônico para a realização do processo administrativo no âmbito dos órgãos e das entidades da administração pública federal direta, autárquica e fundacional.','Desde 2016, o Ministério da Ciência, Tecnologia e Inovação tornou eletrônicos todos os processos em tramitação no órgão, trabalhando-os de forma mais integrada e ágil a partir de uma plataforma virtual. O que motivou a iniciativa foi, dentre outros ganhos, a possibilidade de diminuir ao mínimo possível o estoque de papel (contribuindo para economia de recursos públicos e preservação do meio ambiente) e dar mais agilidade às análises.Estas diretrizes compõem o Decreto nº 8.539, de 08 de outubro de 2015 , que dispõe sobre o uso do meio eletrônico para a realização do processo administrativo no âmbito dos órgãos e das entidades da administração pública federal direta, autárquica e fundacional.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://www.gov.br/mcti/pt-br/acesso-a-informacao/processo-eletronico',NULL,1,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','7f379ee04d87f3648744face2c272439f0198833ce4127e97af381c80051f08a','cf41437d5d0094fac5ddf42f2cda2c13ea1cf98f0f0ed4375de0f71cd953982c',1,1,1,1 FROM sources WHERE root_url='https://www.gov.br/mcti/pt-br/composicao/rede-mcti/agencia-espacial-brasileira' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
INSERT INTO document_search(document_id,search_text,updated_at) SELECT id,'gestao documental e processo eletronico ministerio da ciencia tecnologia e inovacao desde 2016 o ministerio da ciencia tecnologia e inovacao tornou eletronicos todos os processos em tramitacao no orgao trabalhando-os de forma mais integrada e agil a partir de uma plataforma virtual. o que motivou a iniciativa foi dentre outros ganhos a possibilidade de diminuir ao minimo possivel o estoque de papel contribuindo para economia de recursos publicos e preservacao do meio ambiente e dar mais agilidade as analises.estas diretrizes compoem o decreto n 8.539 de 08 de outubro de 2015 que dispoe sobre o uso do meio eletronico para a realizacao do processo administrativo no ambito dos orgaos e das entidades da administracao publica federal direta autarquica e fundacional. research',CURRENT_TIMESTAMP FROM documents WHERE canonical_hash='cf41437d5d0094fac5ddf42f2cda2c13ea1cf98f0f0ed4375de0f71cd953982c' ON CONFLICT(document_id) DO UPDATE SET search_text=excluded.search_text,updated_at=CURRENT_TIMESTAMP;
