INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-460C5CF26F608413FEDF','research',NULL,'PGD | Programa de Gestão e Desempenho — Ministério da Ciência, Tecnologia e Inovação','https://www.gov.br/mcti/pt-br/acesso-a-informacao/institucional/programa-de-gestao',NULL,'AEB - Agência Espacial Brasileira',NULL,'Brazil','South America','government_science_network_unit',NULL,NULL,'2026-10-04T10:26:41.676Z','institutional_primary','pt','O Programa de Gestão e Desempenho (PGD) foi um modelo de trabalho inicialmente previsto pelo Decreto nº 1.590, de 10 de agosto de 1995 , que além de tratar sobre a jornada de trabalho dos servidores da Administração Pública Federal direta, autárquica e fundacional mencionava a implementação do PGD. Contudo, o Programa só começou a ser implementado de forma generalizada quando a Instrução Normativa nº 65, de 30 de julho de 2020 , trouxe as ferramentas necessárias à sua inclusão na pauta do serviço público brasileiro.','O Programa de Gestão e Desempenho (PGD) foi um modelo de trabalho inicialmente previsto pelo Decreto nº 1.590, de 10 de agosto de 1995 , que além de tratar sobre a jornada de trabalho dos servidores da Administração Pública Federal direta, autárquica e fundacional mencionava a implementação do PGD. Contudo, o Programa só começou a ser implementado de forma generalizada quando a Instrução Normativa nº 65, de 30 de julho de 2020 , trouxe as ferramentas necessárias à